/// A parameter of a signal declared in QML: `int a`, `a: int`.
#[derive(Clone, Debug, PartialEq)]
pub struct SigParam {
    pub name: String,
    /// The declared QML type an emitted argument is converted to; `var` converts nothing.
    pub ty: Sym,
}

impl SigParam {
    /// A parameter that takes any value as it is.
    pub fn untyped(name: &str) -> Self {
        SigParam {
            name: name.to_string(),
            ty: sym!("var"),
        }
    }

    /// The parameters of a declaration's `(int a, b: string)` text.
    fn parse(params: &str) -> Vec<Self> {
        params
            .split(',')
            .filter_map(|p| {
                let p = p.trim();
                let (name, ty) = match p.split_once(':') {
                    Some((n, t)) => (n.trim(), t.trim()),
                    None => match p.rsplit_once(char::is_whitespace) {
                        Some((t, n)) => (n, t.trim()),
                        None => (p, "var"),
                    },
                };
                (!name.is_empty()).then(|| SigParam {
                    name: name.to_string(),
                    ty: Sym::new(ty),
                })
            })
            .collect()
    }
}

pub fn default_for(ty: &str) -> Value {
    match ty {
        "int" | "real" | "double" | "number" => Value::Num(0.0),
        "bool" => Value::Bool(false),
        "string" | "url" => Value::str(""),
        "color" => Value::Color(crate::color::Color::INVALID),
        // QDateTime(): an invalid date.
        "date" | "QDateTime" => crate::builtins::plain_date(f64::NAN),
        "var" | "variant" | "function" => Value::Undefined,
        t if t.starts_with("list") => Value::array(Vec::new()),
        t => crate::valuetypes::Vt::of_type(t).map_or(Value::Null, crate::valuetypes::unset_value),
    }
}

fn coerce(ty: &str, v: Value) -> Value {
    match ty {
        // QV4 stores a number in an int property with ToInt32 (wrapping, not clamping).
        "int" => Value::Num(crate::eval::to_i32(v.to_number()) as f64),
        "real" | "double" | "number" => Value::Num(v.to_number()),
        "bool" => Value::Bool(v.truthy()),
        "string" | "url" => match v {
            Value::Undefined | Value::Null => Value::str(""),
            // A QString keeps an unpaired surrogate (UTF-16); a QUrl is UTF-8.
            v @ Value::Str16(_) if ty == "string" => v,
            v => match crate::valuetypes::url_written(&v).filter(|_| ty == "url") {
                // A url QUrl calls invalid stays the url it was.
                Some(written) => Value::Str(written),
                None => Value::str(&v.to_js_string()),
            },
        },
        "color" => Value::Color(crate::builtins::to_color(&v)),
        // The property keeps a QDateTime of its own: whole milliseconds, apart from the Date
        // script wrote. A string is an ISO 8601 date (QQmlStringConverters).
        "date" | "QDateTime" => match &v {
            Value::Str(s) => {
                crate::builtins::qt_iso_datetime(s).map_or(v, crate::builtins::plain_date)
            }
            _ => match crate::builtins::date_ms(&v) {
                Some(ms) => crate::builtins::plain_date(ms.trunc()),
                None => v,
            },
        },
        t => match crate::valuetypes::Vt::of_type(t) {
            Some(vt) => crate::valuetypes::convert_plain(&v, vt).unwrap_or(v),
            None => v,
        },
    }
}

/// Steps `World::text_emit` sends one at a time, running handlers in between.
pub type TextSteps = Vec<(&'static str, Value)>;

/// What a WidgetHost was last synced from: its `widgetType`, its loaded widget, the widget
/// registry revision and its `settings` and `placement` values. An object value is compared
/// by identity (as a `var` property's change is), and holding it keeps its address from
/// being reused by another.
#[derive(Clone, Debug)]
pub struct WidgetHostSynced {
    widget_type: String,
    item: Option<usize>,
    registry: u64,
    settings: Value,
    placement: Value,
}

impl WidgetHostSynced {
    /// Whether nothing the host's sync reads changed since `self`. Settings given as an item
    /// are never fresh: its properties change without the value changing.
    fn fresh(&self, now: &WidgetHostSynced) -> bool {
        self.widget_type == now.widget_type
            && self.item == now.item
            && self.registry == now.registry
            && !matches!(now.settings, Value::Item(_))
            && self.settings.strict_eq(&now.settings)
            && self.placement.strict_eq(&now.placement)
    }
}

/// What a `LayoutState` showed: the container kinds the layout has and its panel edges.
pub type LayoutStateSynced = Shown<(), (Vec<&'static str>, Vec<(String, &'static str)>)>;
/// What a `SidebarContainer` or `DesktopContainer` showed: connector, container id, for a
/// desktop its size and the revision of its natural sizes, the widget registry revision, and
/// for a desktop the widget shown mid-drag ([`crate::edit_mode::live_desktop`]) and for a
/// sidebar the one resized, the columns it spans as the rect's width
/// ([`crate::edit_mode::live_sidebar`]); the container
/// they found and, for a desktop, the unplugged monitors' containers it shows meanwhile
/// ([`crate::desktop_container::Guests`]).
pub type LayoutViewSynced = Shown<
    (
        String,
        String,
        (u32, u32),
        u64,
        u64,
        Option<(String, crate::layout_model::desktop::Rect, bool)>,
    ),
    (
        Option<crate::layout_model::Container>,
        crate::desktop_container::Guests,
    ),
>;

type TextStage = (usize, Sym, Vec<(&'static str, Value)>, Option<usize>);

/// The script methods of QQuickTextInput and QQuickTextEdit that move the selection or change
/// the text. Arguments are C++ `int`s; positions are UTF-16 code units.
fn text_edit_method(w: &mut World, item: usize, name: &str, args: &[Value]) -> (Value, TextSteps) {
    w.flush_text_pending();
    let mut t = units_of(w.read(item, "text").as_ref());
    let n = t.len();
    let int = |k: usize| {
        args.get(k)
            .map_or(0, |v| i64::from(crate::eval::to_i32(v.to_number())))
    };
    let (a, b) = (int(0), int(1));
    // Positions outside the text: select() and insert() do nothing, remove() and getText()
    // move them to the nearest end.
    let inside = |x: i64| (0..=n as i64).contains(&x);
    let at = |x: i64| x.clamp(0, n as i64) as usize;
    let (lo, hi) = (at(a.min(b)), at(a.max(b)));
    let nothing = (Value::Undefined, Vec::new());
    let stored = |w: &mut World, k: &str, or: usize| {
        w.read(item, k)
            .map(|v| v.to_number())
            .filter(|x| x.is_finite())
            .map_or(or, |x| at(x as i64))
    };
    let cur = stored(w, "cursorPosition", n);
    let (s0, s1) = (
        stored(w, "selectionStart", cur),
        stored(w, "selectionEnd", cur),
    );
    let (s0, s1) = (s0.min(s1), s0.max(s1));
    let inserted = || match args.get(1) {
        Some(v) if v.is_str() => units_of(Some(v)),
        Some(v) => v.to_js_string().encode_utf16().collect(),
        None => Vec::new(),
    };
    // QTextCursor after a removal of lo..hi, QQuickTextInput's cursor and selection start too.
    let gone = |x: usize| if x > lo { x - (x.min(hi) - lo) } else { x };
    let single = w.items[item].prop_info("acceptableInput").is_some();
    // With an inputMask the positions of select(), deselect() and getText() are in m_text,
    // which is as long as the mask whatever is filled in: the text shown, blanks included.
    let shown = match single && w.input_mask(item).is_some() {
        true => Some(units_of(w.read(item, "displayText").as_ref())),
        false => None,
    };
    if name == "getText" {
        let m = shown.as_deref().unwrap_or(&t);
        let at = |x: i64| x.clamp(0, m.len() as i64) as usize;
        return (
            Value::from_utf16(&m[at(a.min(b))..at(a.max(b))]),
            Vec::new(),
        );
    }
    if matches!(name, "cut" | "copy") {
        // QQuickTextInput copies and cuts only with echoMode Normal; QQuickTextEdit has none.
        let normal = !single || w.read(item, "echoMode").map_or(0.0, |v| v.to_number()) == 0.0;
        let ro = w.read(item, "readOnly").is_some_and(|v| v.truthy());
        // QQuickTextControl::cut needs a selection; QQuickTextInput::cut ends in del().
        let cuts = name == "cut" && !ro && normal && (single || s0 < s1);
        if (name == "copy" || cuts) && normal && s0 < s1 {
            clipboard_set(String::from_utf16_lossy(&t[s0..s1]));
        }
        if !cuts {
            return nothing;
        }
        if !single {
            // QTextCursor::removeSelectedText on the control's own cursor, as a key does.
            t.drain(s0..s1);
            return (
                Value::Undefined,
                w.text_steps(item, &t, s0, (s0, s0), TextOp::Edit),
            );
        }
        let method = |sel_dirty| TextOp::Method {
            sel_dirty,
            edited: true,
        };
        let steps = if s0 < s1 {
            // removeSelectedText ends in internalDeselect: m_selstart = m_selend = 0.
            t.drain(s0..s1);
            let c = if cur > s0 {
                cur - (cur.min(s1) - s0)
            } else {
                cur
            };
            w.text_steps(item, &t, c, (0, 0), method(true))
        } else if cur < n {
            // QQuickTextInputPrivate::del without a selection deletes the next character.
            let pair = t.get(cur + 1).is_some_and(|u| (0xDC00..0xE000).contains(u))
                && (0xD800..0xDC00).contains(&t[cur]);
            t.drain(cur..cur + 1 + usize::from(pair));
            let rest = w.text_sel_rest.get(&item).copied().unwrap_or_default();
            w.text_steps(item, &t, cur, rest, method(false))
        } else {
            return nothing;
        };
        return (Value::Undefined, steps);
    }
    if let (Some(d), Some(m), "insert" | "remove") = (&shown, w.input_mask(item), name) {
        // QQuickTextInput::insert and remove with m_maskData replace in m_text, which keeps
        // its length: `m_text.replace(position, insertText.size(), insertText)` with
        // maskString's text, and clearString over what is removed. The cursor and the
        // selection stay where they are.
        let len = d.len() as i64;
        let mut d: Vec<char> = String::from_utf16_lossy(d).chars().collect();
        let (p, put) = match name {
            "insert" if (0..=len).contains(&a) => {
                let ins: Vec<char> = String::from_utf16_lossy(&inserted()).chars().collect();
                (a as usize, m.mask_string(a as usize, &ins, false, &d))
            }
            "insert" => return nothing,
            _ => {
                let (lo, hi) = (a.min(b).clamp(0, len), a.max(b).clamp(0, len));
                (lo as usize, m.clear(lo as usize, (hi - lo) as usize))
            }
        };
        if put.is_empty() {
            return nothing;
        }
        let end = p + put.len();
        d.splice(p..end, put);
        w.write_raw(
            item,
            "displayText",
            Value::str(&d.iter().collect::<String>()),
        );
        let t: Vec<u16> = m.strip(&d).encode_utf16().collect();
        let stored = |w: &mut World, k: &str| {
            w.read(item, k)
                .map(|v| v.to_number())
                .filter(|x| x.is_finite())
                .map_or(len, |x| (x as i64).clamp(0, len)) as usize
        };
        let cur = stored(w, "cursorPosition");
        let sel = (stored(w, "selectionStart"), stored(w, "selectionEnd"));
        let sel = match sel.0 < sel.1 {
            true => sel,
            false => w.text_sel_rest.get(&item).copied().unwrap_or_default(),
        };
        let op = TextOp::Method {
            sel_dirty: p < sel.1 && end > sel.0,
            edited: true,
        };
        return (Value::Undefined, w.text_steps(item, &t, cur, sel, op));
    }
    if single {
        // m_selstart / m_selend: the selection shown, or the pair kept while nothing is.
        let (ms, me) = if s0 < s1 {
            (s0, s1)
        } else {
            w.text_sel_rest.get(&item).copied().unwrap_or_default()
        };
        let method = |sel_dirty, edited| TextOp::Method { sel_dirty, edited };
        return match name {
            "insert" if inside(a) => {
                let mut ins = inserted();
                // `insertText.left(m_maxLength - m_text.size())`, nothing at all once full.
                let room = w.max_length(item).saturating_sub(n);
                if room == 0 {
                    return nothing;
                }
                ins.truncate(room);
                let (p, k) = (a as usize, ins.len());
                t.splice(p..p, ins);
                let sh = |x: usize| if x >= p { x + k } else { x };
                let (ms, me) = (sh(ms), sh(me));
                let steps = w.text_steps(
                    item,
                    &t,
                    sh(cur),
                    (ms, me),
                    method(p >= ms && p <= me, true),
                );
                (Value::Undefined, steps)
            }
            "remove" if lo < hi => {
                t.drain(lo..hi);
                let sel = (gone(ms), if me >= hi { me - (hi - lo) } else { me });
                let steps =
                    w.text_steps(item, &t, gone(cur), sel, method(lo < me && hi > ms, true));
                (Value::Undefined, steps)
            }
            // QQuickTextInputPrivate::clear selects everything and removes the selection.
            "clear" if n > 0 => {
                let steps = w.text_steps(item, &[], 0, (0, 0), method(true, false));
                (Value::Undefined, steps)
            }
            "insert" | "remove" | "clear" => nothing,
            _ => {
                let m = shown.as_ref().map_or(n, Vec::len);
                let inside = |x: i64| (0..=m as i64).contains(&x);
                if name == "select" && (!inside(a) || !inside(b)) {
                    return nothing;
                }
                let at = |x: i64| x.clamp(0, m as i64) as usize;
                let stored = |w: &mut World, k: &str, or: usize| {
                    w.read(item, k)
                        .map(|v| v.to_number())
                        .filter(|x| x.is_finite())
                        .map_or(or, |x| at(x as i64))
                };
                let cur = stored(w, "cursorPosition", m);
                let (s0, s1) = (
                    stored(w, "selectionStart", cur),
                    stored(w, "selectionEnd", cur),
                );
                let (s0, s1) = (s0.min(s1), s0.max(s1));
                let (sel, c) = match name {
                    // QQuickTextInput::selectAll: `setSelection(0, text().size())`, the
                    // length of the text without the mask's blanks.
                    "selectAll" => ((0, n), n),
                    "select" => ((at(a.min(b)), at(a.max(b))), b as usize),
                    _ => ((cur, cur), cur),
                };
                // QQuickTextInputPrivate::setSelection returns early for the selection it
                // already has.
                if sel.0 < sel.1 && sel == (s0, s1) && c == cur && name != "deselect" {
                    return nothing;
                }
                let op = if name == "select" {
                    TextOp::Select
                } else {
                    TextOp::SelectAll
                };
                (Value::Undefined, w.text_steps(item, &t, c, sel, op))
            }
        };
    }
    let (sel, c) = match name {
        "clear" => {
            t.clear();
            ((0, 0), 0)
        }
        "insert" | "select" if !inside(a) || (name == "select" && !inside(b)) => {
            return nothing;
        }
        "insert" => {
            let ins = inserted();
            let (p, k) = (a as usize, ins.len());
            t.splice(p..p, ins);
            // QTextCursor: a position at or after an insertion moves with it.
            let sh = |x: usize| if x >= p { x + k } else { x };
            ((sh(s0), sh(s1)), sh(cur))
        }
        "remove" => {
            t.drain(lo..hi);
            ((gone(s0), gone(s1)), gone(cur))
        }
        "selectAll" => ((0, n), n),
        "select" => ((lo, hi), b as usize),
        _ => ((cur, cur), cur),
    };
    let op = match name {
        "remove" => TextOp::Cut {
            at_cursor: lo < hi && cur >= lo,
        },
        "clear" | "insert" => TextOp::Edit,
        "selectAll" | "deselect" => TextOp::SelectAll,
        _ => TextOp::Select,
    };
    (Value::Undefined, w.text_steps(item, &t, c, sel, op))
}

thread_local! {
    /// What the editors' `cut()` and `copy()` gave the clipboard in this thread's tests.
    #[cfg(test)]
    static CLIP_SET: RefCell<Vec<String>> = const { RefCell::new(Vec::new()) };
}

/// `QGuiApplication::clipboard()->setText(text)`.
fn clipboard_set(text: String) {
    #[cfg(test)]
    CLIP_SET.with(|c| c.borrow_mut().push(text));
    #[cfg(not(test))]
    crate::ports::clip::set_text(text)
}

/// A string value's UTF-16 code units (QString's); none for a non-string.
fn units_of(v: Option<&Value>) -> Vec<u16> {
    v.and_then(Value::js_str)
        .map_or_else(Vec::new, |s| s.units().into_owned())
}

/// What a write to an Item's `children`/`data`/`resources` does with the list it has.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
enum ListWrite {
    /// A JS assignment or binding: the new list replaces it.
    #[default]
    Assign,
    /// A list of object literals: each is appended.
    Append,
    /// The write-back of an in-place change (`push`, `length`): only the tail changes.
    WriteBack,
}

/// What a `Binding` object found on its target property (QQmlBindPrivate::prevBind /
/// prevValue), for the day its `when` turns false.
struct BindSaved {
    target: usize,
    property: String,
    value: Value,
    binding: Option<Code>,
}

/// One step of a write to an Item's `children`/`data`/`resources`: the object leaves `item`'s
/// list or joins it.
#[derive(Clone, Copy)]
struct ListStep {
    item: usize,
    object: usize,
    join: bool,
    /// The object was made inside the item's declaration and joins its list for the first
    /// time.
    declared: bool,
    /// A step of the `resources` list alone: no object changes its parent.
    res: bool,
}

/// How an editor change came about: picks Qt 6.12's notify order in `World::text_steps`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum TextOp {
    /// A cursor move; `mark` keeps the anchor (Shift+arrows, mouse selection).
    Move { mark: bool },
    /// The text changed (typing, Backspace/Delete, paste, insert/remove/clear).
    Edit,
    /// `select()` / `cursorPosition` assignment.
    Select,
    /// `selectAll()`, Ctrl+A, `deselect()`: QQuickTextEdit emits no cursorPositionChanged.
    SelectAll,
    /// QQuickTextInput's `insert()`, `remove()` and `clear()`: `sel` is m_selstart / m_selend
    /// as the method left them, `sel_dirty` its m_selDirty, and `edited` whether finishChange
    /// emits `textEdited` (not for `clear()`).
    Method { sel_dirty: bool, edited: bool },
    /// QQuickTextEdit's `remove()`: QTextDocument reports a cursor at or after the start of
    /// the removed range as changed (`at_cursor`), also when it stays where it is.
    Cut { at_cursor: bool },
}

/// A `Stop` that is set when its owner is dropped.
#[derive(Default)]
pub struct StopOnDrop(pub std::sync::Arc<crate::svc::Stop>);

impl Drop for StopOnDrop {
    fn drop(&mut self) {
        self.0.store(true, std::sync::atomic::Ordering::Release);
    }
}

impl World {
    /// Replaces the widget registry; views resolving widget types sync again.
    pub fn set_widgets(&mut self, r: crate::widgets::Registry) {
        self.widgets = Rc::new(r);
        self.widgets_revision += 1;
        self.deleg_gen += 1;
        self.revision += 1;
        self.cap_layout_sizes();
    }

    /// The layout shows no desktop widget larger than its type's largest desktop size
    /// ([`crate::layout_model::Live::cap_desktop_sizes`]): after the layout is read and after
    /// the registry that holds the limits is.
    pub(crate) fn cap_layout_sizes(&mut self) {
        let Some(live) = self.layout.as_mut() else {
            return;
        };
        let widgets = self.widgets.clone();
        let px = |v: f64| v.max(1.0).min(u32::MAX as f64) as u32;
        live.cap_desktop_sizes(|ty| {
            let v = widgets
                .get(ty)?
                .variant(crate::widgets::Placement::Desktop)?;
            Some((px(v.size.max.w), px(v.size.max.h)))
        });
    }

    /// Qt 6.12's change signals for editor `item` going to `text`/`cursor`/`sel`.
    /// QQuickTextInput (finishChange -> selectionChanged -> emitCursorPositionChanged) keeps
    /// cursorPosition and selectedText live but selectionStart/End at their last emitted values;
    /// QQuickTextEdit (QQuickTextControl) keeps every selection getter live and `text` stale.
    /// Live getters are stored here without notifying; each returned step is a notify.
    /// `text` and the positions are QString's: UTF-16 code units, a position may split a pair.
    pub fn text_steps(
        &mut self,
        item: usize,
        text: &[u16],
        cursor: usize,
        sel: (usize, usize),
        op: TextOp,
    ) -> TextSteps {
        self.flush_text_pending();
        let old_text = units_of(self.read(item, "text").as_ref());
        // With an inputMask, positions and selectedText are in the display text.
        let edit = self
            .text_edit
            .as_ref()
            .filter(|e| e.0 == item)
            .and_then(|e| e.2.clone());
        let shown = match edit {
            Some(d) => Some(d),
            None if self.input_mask(item).is_some() => {
                self.read(item, "displayText").map(|v| v.to_js_string())
            }
            None => None,
        };
        let shown: Option<Vec<u16>> = shown.map(|d| d.encode_utf16().collect());
        let cs = shown.as_deref().unwrap_or(text);
        let num = |w: &mut World, k: &str| {
            w.read(item, k)
                .map(|v| v.to_number())
                .filter(|x| x.is_finite())
                .map_or(0, |x| x.max(0.0) as usize)
        };
        let c0 = num(self, "cursorPosition");
        let (ls, le) = (num(self, "selectionStart"), num(self, "selectionEnd"));
        let cursor = cursor.min(cs.len());
        let (s0, s1) = (
            sel.0.min(sel.1).min(cs.len()),
            sel.0.max(sel.1).min(cs.len()),
        );
        let method = match op {
            TextOp::Method { sel_dirty, edited } => Some((sel_dirty, edited)),
            _ => None,
        };
        // QQuickTextInputPrivate::hasSelectedText; a method may leave m_selend past the text.
        let has = if method.is_some() {
            sel.0 < sel.1 && !cs.is_empty()
        } else {
            s0 < s1
        };
        let picked = Value::from_utf16(&cs[s0..s1]);
        let st = picked.clone();
        let (ns, ne) = match (has, method) {
            (true, Some(_)) => sel,
            (true, None) => (s0, s1),
            (false, _) => (cursor, cursor),
        };
        let n = |x: usize| Value::Num(x as f64);
        let (edited, old_has) = (old_text != text, ls < le);
        let shown = shown.is_some();
        if !self.text_replaying && !shown {
            let line = self.items[item].prop_info("acceptableInput").is_some();
            if edited {
                let from = crate::undo::Caret {
                    cursor: c0,
                    sel: (ls, le),
                };
                self.text_undo
                    .entry(item)
                    .or_insert_with(|| crate::undo::History::new(line))
                    .record(&old_text, text, from, cursor);
            } else if cursor != c0
                && let Some(h) = self.text_undo.get_mut(&item)
            {
                h.moved();
            }
        }
        let mut out: TextSteps = Vec::new();
        if self.items[item].prop_info("acceptableInput").is_some() {
            self.text_quiet(item, "cursorPosition", n(cursor));
            self.text_quiet(item, "selectedText", st.clone());
            // The methods set m_textDirty whatever they inserted: `insert(0, "")` notifies.
            if edited || method.is_some() || (self.text_edit_dirty == Some(item) && !shown) {
                if matches!(method, Some((_, true))) {
                    out.push(("textEdited", Value::from_utf16(text)));
                }
                out.push(("text", Value::from_utf16(text)));
            }
            let dirty = match op {
                TextOp::Move { mark } => mark || old_has,
                TextOp::Edit | TextOp::Cut { .. } => old_has,
                TextOp::Select | TextOp::SelectAll => old_has || has,
                TextOp::Method { sel_dirty, .. } => sel_dirty,
            };
            let (mut ls, mut le) = (ls, le);
            if dirty {
                // QQuickTextInput::selectionChanged: a -1 (no selection) getter always differs.
                out.push(("selectedText", st));
                if !has || ls != ns {
                    out.push(("selectionStart", n(ns)));
                }
                if !has || le != ne {
                    out.push(("selectionEnd", n(ne)));
                }
                (ls, le) = (ns, ne);
            }
            if cursor != c0 {
                out.push(("cursorPosition", n(cursor)));
            }
            if method.is_none() {
                if ls != ns {
                    out.push(("selectionStart", n(ns)));
                }
                if le != ne {
                    out.push(("selectionEnd", n(ne)));
                }
            } else {
                // emitCursorPositionChanged moves the selection ends with the cursor while
                // nothing is selected; then the method reports m_selstart / m_selend where
                // the last reported ends differ from each other.
                if cursor != c0 && !has {
                    if ls != cursor {
                        out.push(("selectionStart", n(cursor)));
                    }
                    if le != cursor {
                        out.push(("selectionEnd", n(cursor)));
                    }
                    (ls, le) = (cursor, cursor);
                }
                if ls != le {
                    if ls != sel.0 {
                        out.push(("selectionStart", n(sel.0)));
                    }
                    if le != sel.1 {
                        out.push(("selectionEnd", n(sel.1)));
                    }
                    (ls, le) = sel;
                }
            }
            // m_selstart / m_selend while they are not the reported selection ends.
            let rest = self.text_sel_rest.get(&item).copied();
            let rest = match op {
                TextOp::Method { .. } => Some(sel).filter(|&m| !has || m != (ls, le)),
                TextOp::Move { mark: true } if !has => Some((cursor, cursor)),
                // Typing leaves them alone, and so does setSelection while they are equal.
                TextOp::Edit if !old_has => rest,
                TextOp::Select if !has => rest.filter(|m| m.0 == m.1),
                // internalDeselect, or the selection now shown.
                _ => None,
            };
            match rest.filter(|&m| m != (0, 0)) {
                Some(m) => self.text_sel_rest.insert(item, m),
                None => self.text_sel_rest.remove(&item),
            };
        } else {
            for (k, v) in [
                ("selectedText", st),
                ("cursorPosition", n(cursor)),
                ("selectionStart", n(ns)),
                ("selectionEnd", n(ne)),
            ] {
                self.text_quiet(item, k, v);
            }
            // The document has changed by the time QQuickTextControl reports the cursor and
            // the selection: `text` reads it unless it holds a text read before.
            if edited {
                match self.text_read.get_mut(&item) {
                    Some(len) => *len = Some(text.len()),
                    None => self.text_quiet(item, "text", Value::from_utf16(text)),
                }
            }
            let sel_changed = old_has != has || (has && (ls, le) != (s0, s1));
            let moved = cursor != c0 || op == (TextOp::Cut { at_cursor: true });
            // QQuickTextEdit::updateSelection runs on each control signal; only the first differs.
            let mut upd = Some(());
            let (es, ee) = match self.text_sel_seen.get(&item) {
                Some(&seen) => seen,
                None => (ls as i64, le as i64),
            };
            let mut update = |out: &mut TextSteps| {
                if upd.take().is_some() {
                    if es != ns as i64 {
                        out.push(("selectionStart", n(ns)));
                    }
                    if ee != ne as i64 {
                        out.push(("selectionEnd", n(ne)));
                    }
                }
            };
            match op {
                TextOp::Move { .. } | TextOp::Edit | TextOp::Method { .. } | TextOp::Cut { .. } => {
                    if moved {
                        update(&mut out);
                        out.push(("cursorPosition", n(cursor)));
                    }
                    if sel_changed || op == (TextOp::Move { mark: true }) {
                        out.push(("selectedText", picked.clone()));
                        update(&mut out);
                    }
                }
                TextOp::Select | TextOp::SelectAll => {
                    if sel_changed {
                        out.push(("selectedText", picked.clone()));
                        update(&mut out);
                    }
                    if moved && op == TextOp::Select {
                        update(&mut out);
                        out.push(("cursorPosition", n(cursor)));
                    }
                }
            }
            if upd.is_none() {
                self.text_sel_seen.remove(&item);
            }
            if edited {
                out.push(("text", Value::from_utf16(text)));
            }
        }
        // QQuickTextInputPrivate::emitUndoRedoChanged closes finishChange; QTextDocument's
        // undoAvailable / redoAvailable follow its contentsChange.
        for (name, on) in self.text_undo_state(item) {
            if self.read(item, name).is_some_and(|v| v.truthy()) != on {
                out.push((name, Value::Bool(on)));
            }
        }
        out
    }

    /// QQuickTextInput / QQuickTextEdit canUndo and canRedo, from the history. A read-only
    /// TextInput has neither (QQuickTextInputPrivate::isUndoAvailable); a document keeps them.
    fn text_undo_state(&mut self, item: usize) -> [(&'static str, bool); 2] {
        let line = self.items[item].prop_info("acceptableInput").is_some();
        let live = !(line && self.read(item, "readOnly").is_some_and(|v| v.truthy()));
        let h = self.text_undo.get(&item);
        [
            ("canUndo", live && h.is_some_and(|h| h.can_undo())),
            ("canRedo", live && h.is_some_and(|h| h.can_redo())),
        ]
    }

    /// What a write to editor `item`'s `name` does to its cursor. QQuickTextInput and
    /// QQuickTextEdit: a focus event shows or hides the cursor of an editor that is not read
    /// only; setReadOnly, once it moved the cursor (`write_told`), hides it, or shows it in an
    /// editor with active focus; setCursorVisible and setCursorDelegate make or drop the
    /// cursor item (`cursor_items_sync`).
    fn cursor_written(&mut self, item: usize, name: &str) {
        let on = |w: &mut Self, k: &str| w.read(item, k).is_some_and(|v| v.truthy());
        match name {
            "activeFocus" => {
                if !on(self, "readOnly") {
                    let focus = on(self, "activeFocus");
                    self.write(item, "cursorVisible", Value::Bool(focus));
                }
            }
            "readOnly" => {
                if on(self, "readOnly") {
                    self.write(item, "cursorVisible", Value::Bool(false));
                } else if on(self, "activeFocus") {
                    self.write(item, "cursorVisible", Value::Bool(true));
                }
            }
            _ => self.cursor_sync.push(item),
        }
    }

    fn text_undo_flags(&mut self, item: usize) {
        for (name, on) in self.text_undo_state(item) {
            if self.read(item, name).is_some_and(|v| v.truthy()) != on {
                self.write(item, name, Value::Bool(on));
            }
        }
    }

    /// QQuickTextInput::undo / redo and QQuickTextEdit::undo / redo: the change signals of one
    /// history step back (or forward); empty when there is none.
    pub fn text_replay(&mut self, item: usize, undo: bool) -> TextSteps {
        self.flush_text_pending();
        // QQuickTextInput::undo checks m_readOnly; QQuickTextEdit::undo does not.
        let line = self.items[item].prop_info("acceptableInput").is_some();
        if line && self.read(item, "readOnly").is_some_and(|v| v.truthy()) {
            return Vec::new();
        }
        let text = units_of(self.read(item, "text").as_ref());
        let cursor = self
            .read(item, "cursorPosition")
            .map(|v| v.to_number())
            .filter(|x| x.is_finite())
            .map_or(0, |x| x.max(0.0) as usize);
        let step = self
            .text_undo
            .get_mut(&item)
            .and_then(|h| h.replay(undo, &text, cursor));
        let Some((text, cursor, sel)) = step else {
            return Vec::new();
        };
        self.text_replaying = true;
        // internalUndo / internalRedo: internalDeselect.
        self.text_sel_rest.remove(&item);
        let steps = self.text_steps(item, &text, cursor, sel, TextOp::Edit);
        self.text_replaying = false;
        steps
    }

    fn text_quiet(&mut self, item: usize, name: &str, v: Value) {
        let p = self.items[item]
            .props
            .entry_sym(Sym::new(name))
            .or_insert_with(|| Prop {
                ty: Sym::new("var"),
                ..Default::default()
            });
        p.value = coerce(&p.ty, v);
        self.memo_invalidate(item);
        if drawn(&self.items[item]) {
            self.touched.push(item);
        }
        if matches!(name, "cursorPosition" | "text") && self.cursor_tracked.contains(&item) {
            self.cursor_dirty.insert(item);
        }
        // An edited TextArea/TextField changes its implicit size, like a `text` write.
        if name == "text" && local_relayout_trigger(&self.items[item]) {
            self.resized.push(item);
        }
    }

    /// The formats of the text of `item` changed without a property write (a
    /// QSyntaxHighlighter's, QTextDocument::markContentsDirty): it is measured and drawn again.
    pub fn text_restyled(&mut self, item: usize) {
        self.memo_invalidate(item);
        self.touched.push(item);
        if local_relayout_trigger(&self.items[item]) {
            self.resized.push(item);
        }
    }

    /// Queues one `text_steps` step; a QQuickTextInput selection end is stored when dispatched.
    /// Its cursor position is stored at once and again when dispatched: one write can move the
    /// cursor twice (QQuickTextInput::setInputMask: internalSetText leaves it at the end of the
    /// text, moveCursor takes it to the first blank), and each cursorPositionChanged handler
    /// reads the position of its own step.
    fn text_defer(&mut self, item: usize, name: &str, v: Value) {
        let line = self.items[item].prop_info("acceptableInput").is_some();
        let sym = Sym::new(name);
        if line && matches!(name, "selectionStart" | "selectionEnd") {
            self.text_pending.push((item, sym, v, false));
        } else {
            if line && name == "cursorPosition" {
                self.text_pending.push((item, sym, v.clone(), true));
            }
            self.text_quiet(item, name, v);
        }
        self.notify(item, name);
    }

    /// Stores the deferred values `text_steps` reads (the selection). With `all`, every value
    /// whose change was never dispatched (e.g. during creation).
    fn flush_text_pending_of(&mut self, all: bool) {
        for (item, _, values, len) in std::mem::take(&mut self.text_stage) {
            self.text_stage_store(item, values, len);
        }
        let (kept, pending): (Vec<_>, Vec<_>) = std::mem::take(&mut self.text_pending)
            .into_iter()
            .partition(|p| !all && p.3);
        self.text_pending = kept;
        for (item, name, v, stored) in pending {
            self.text_restore(item, name, v, stored);
        }
    }

    fn flush_text_pending(&mut self) {
        self.flush_text_pending_of(false)
    }

    fn apply_text_pending(&mut self, item: usize, name: &str) {
        let key = (item, Sym::new(name));
        if let Some(k) = self
            .text_pending
            .iter()
            .position(|(i, n, _, _)| (*i, *n) == key)
        {
            let (_, _, v, stored) = self.text_pending.remove(k);
            self.text_restore(item, key.1, v, stored);
        }
    }

    fn apply_text_stage(&mut self, item: usize, name: &str) {
        let key = (item, Sym::new(name));
        if let Some(k) = self.text_stage.iter().position(|s| (s.0, s.1) == key) {
            let (_, _, values, len) = self.text_stage.remove(k);
            self.text_stage_store(item, values, len);
        }
    }

    fn text_stage_store(
        &mut self,
        item: usize,
        values: Vec<(&'static str, Value)>,
        len: Option<usize>,
    ) {
        for (name, v) in values {
            self.text_restore(item, Sym::new(name), v, true);
        }
        match len {
            Some(n) => self.text_read.insert(item, Some(n)),
            None => self.text_read.remove(&item),
        };
    }

    /// QQuickTextEdit::setText of a complete editor whose text was `old`, after the new text
    /// is stored and its textChanged queued (from `mark` on). QQuickTextControlPrivate::
    /// setContent: an empty text clears the document, which takes the cursor and the selection
    /// to its start; any other text is loaded while the control has no cursor (every position
    /// reads -1), then the cursor is a new one at the start. cursorPositionChanged comes last,
    /// when the position is not the one before the call.
    fn text_edit_assigned(&mut self, item: usize, old: Value, mark: usize) {
        let num = |w: &mut World, k: &str| {
            w.read(item, k)
                .map(|v| v.to_number())
                .filter(|x| x.is_finite())
                .map_or(0, |x| x.max(0.0) as i64)
        };
        let c0 = num(self, "cursorPosition");
        let (ls, le) = (num(self, "selectionStart"), num(self, "selectionEnd"));
        let mut seen = self.text_sel_seen.remove(&item).unwrap_or((ls, le));
        let new = self.read(item, "text").unwrap_or(Value::str(""));
        let empty = new.js_str().is_none_or(|s| s.is_empty());
        let n = |x: i64| Value::Num(x as f64);
        let text = (item, sym!("text"));
        let mut queued = Vec::new();
        for k in (mark..self.changed.len()).rev() {
            if self.changed[k].0 == text {
                queued.push(self.changed.remove(k));
            }
        }
        // QQuickTextEdit::updateSelection.
        let update = |w: &mut World, seen: &mut (i64, i64), at: i64| {
            if seen.0 != at {
                w.notify(item, "selectionStart");
            }
            if seen.1 != at {
                w.notify(item, "selectionEnd");
            }
            *seen = (at, at);
        };
        let mut before = vec![("text", old)];
        let mut first = None;
        if ls < le {
            first = Some("selectedText");
            self.notify(item, "selectedText");
            update(self, &mut seen, if empty { 0 } else { -1 });
        }
        if empty && c0 != 0 {
            first = first.or(Some(if seen == (0, 0) {
                "cursorPosition"
            } else if seen.0 != 0 {
                "selectionStart"
            } else {
                "selectionEnd"
            }));
            update(self, &mut seen, 0);
            self.notify(item, "cursorPosition");
        }
        let at = if empty { 0 } else { -1 };
        for k in ["cursorPosition", "selectionStart", "selectionEnd"] {
            before.push((k, n(at)));
        }
        before.push(("selectedText", Value::str("")));
        for (k, v) in [
            ("cursorPosition", n(0)),
            ("selectionStart", n(0)),
            ("selectionEnd", n(0)),
            ("selectedText", Value::str("")),
        ] {
            self.text_quiet(item, k, v);
        }
        if let Some(first) = first {
            let len = units_of(Some(&new)).len();
            self.text_stage
                .push((item, Sym::new(first), before, Some(len)));
            let after = vec![
                ("text", new),
                ("cursorPosition", n(0)),
                ("selectionStart", n(0)),
                ("selectionEnd", n(0)),
            ];
            self.text_stage.push((item, text.1, after, None));
        }
        self.changed.extend(queued.into_iter().rev());
        if c0 != 0 {
            if !empty {
                update(self, &mut seen, 0);
            }
            self.notify(item, "cursorPosition");
        }
        if seen != (0, 0) {
            self.text_sel_seen.insert(item, seen);
        }
    }

    /// Stores one `text_pending` value; a stored one only when a later step replaced it.
    fn text_restore(&mut self, item: usize, name: Sym, v: Value, stored: bool) {
        if stored
            && self.items[item]
                .props
                .get_sym(name)
                .is_some_and(|p| p.value.strict_eq(&v))
        {
            return;
        }
        self.text_quiet(item, name.as_str(), v);
        self.dirty_from(&(item, name));
    }

    /// Sends one `text_steps` step: stores its value and notifies.
    pub fn text_emit(&mut self, item: usize, name: &str, v: Value) {
        if name == "text" {
            self.text_keep_cursor = true;
            if !self.write(item, name, v) {
                self.notify(item, name);
            }
            self.text_keep_cursor = false;
            if self.items[item].prop_info("acceptableInput").is_some() {
                // An edit stored the text for its textEdited handlers before this step.
                if self.input_mask(item).is_none() {
                    self.update_display_text(item);
                }
                self.update_acceptable(item);
            }
        } else {
            self.text_quiet(item, name, v);
            self.notify(item, name);
        }
    }
}

/// The margins of QQuickAnchors that follow `anchors.margins`, in the order setMargins tells
/// of them.
const ANCHOR_SIDE_MARGINS: [&str; 4] = [
    "anchors.rightMargin",
    "anchors.leftMargin",
    "anchors.topMargin",
    "anchors.bottomMargin",
];

/// The paddings of the four sides, in the order QQuickControl::setPadding and
/// QQuickText::setPadding tell of them.
const SIDE_PADDINGS: [&str; 4] = ["topPadding", "leftPadding", "rightPadding", "bottomPadding"];

/// Where the change signals of the properties that follow a written one go.
#[derive(Clone, Copy, PartialEq)]
enum Follow {
    /// Before the signal of the written one (QQuickAnchors::setMargins,
    /// QQuickLayoutAttached::setMargins).
    Before,
    /// After it (QQuickPopup::setMargins, QQuickText::setPadding).
    After,
    /// QQuickControl: `setPadding` tells of the sides and the two wider ones after
    /// `paddingChanged`, `setHorizontalPadding` of the sides before its own signal, and each
    /// setter ends with `availableWidthChanged` / `availableHeightChanged`.
    Control,
    /// QQuickPopup::paddingChange: the sides that changed, then `horizontalPaddingChanged`
    /// and `availableWidthChanged` for a change of the left or right one,
    /// `verticalPaddingChanged` and `availableHeightChanged` for the top or bottom one,
    /// whichever padding was written; `paddingChanged` comes before them.
    Popup,
    /// The style's bindings of a ComboBox's side paddings read `spacing`: each side that
    /// changes is written by its binding (QQuickControlPrivate::setLeftPadding).
    Bound,
}

/// What the properties that follow a written one showed before the write.
type Followed = (Follow, Vec<(&'static str, Option<Value>)>);

/// The properties that show the value of property `name` of a Qt type while nothing set them
/// (and that property itself, where its setter tells of it as of the others), in the order
/// the setter tells of them.
fn followers(name: &str, popup: bool, control: bool) -> Option<(Follow, &'static [&'static str])> {
    Some(match name {
        "anchors.margins" => (Follow::Before, &ANCHOR_SIDE_MARGINS),
        "Layout.margins" => (
            Follow::Before,
            &[
                "Layout.leftMargin",
                "Layout.topMargin",
                "Layout.rightMargin",
                "Layout.bottomMargin",
            ],
        ),
        "margins" if popup => (
            Follow::After,
            &["topMargin", "leftMargin", "rightMargin", "bottomMargin"],
        ),
        _ if popup && PADDINGS.contains(&name) => (Follow::Popup, &SIDE_PADDINGS),
        _ if control && PADDINGS.contains(&name) => (
            Follow::Control,
            &[
                "topPadding",
                "leftPadding",
                "rightPadding",
                "bottomPadding",
                "verticalPadding",
                "horizontalPadding",
            ],
        ),
        "padding" => (Follow::After, &SIDE_PADDINGS),
        _ => return None,
    })
}

const GROUPS: &[&str] = &["anchors", "font", "border", "margins", "easing", "layer"];

thread_local!(static UPPER_EPOCH: std::cell::Cell<u64> = const { std::cell::Cell::new(0) });
thread_local!(static SCOPE_EPOCH: std::cell::Cell<u64> = const { std::cell::Cell::new(0) });

/// Something an uppercase free name may resolve through changed: drop `World::upper_memo`.
fn bump_upper() {
    UPPER_EPOCH.with(|e| e.set(e.get() + 1));
    bump_scope();
}

/// The shape of a context chain changed (ids, imported scripts, contexts, the set of declared
/// properties): drop `World::scope_memo`.
pub(crate) fn bump_scope() {
    SCOPE_EPOCH.with(|e| e.set(e.get() + 1));
}

/// Where a lowercase free name resolved on its context chain once its scope object missed.
#[derive(Clone)]
enum ScopeHit {
    /// An id of a context on the chain.
    Id(usize),
    /// An imported script (`import "x.js" as name`) of that context.
    Js(usize),
    /// A property of that context's root object, after absent-property reads of `misses`.
    Root { root: usize, misses: Rc<[usize]> },
}

/// Whether `k` is spelled as the name of a QML type.
fn type_name(k: &str) -> bool {
    k.starts_with(|c: char| c.is_ascii_uppercase())
}

/// A property key whose reads can satisfy an uppercase free name (`Foo`, attached `Foo.bar`).
fn upper_key(k: &str) -> bool {
    !k.starts_with(|c: char| c.is_ascii_lowercase() || c == '_')
}

fn prefix_hash(s: &str) -> u64 {
    use std::hash::{BuildHasher, Hasher};
    let mut h = rustc_hash::FxBuildHasher.build_hasher();
    h.write(s.as_bytes());
    h.finish()
}

/// `read_special` memoized by interned address (names are leaked, so addresses are stable).
fn read_special_sym(sym: Sym) -> bool {
    thread_local!(static C: std::cell::Cell<[(usize, bool); 512]> =
        const { std::cell::Cell::new([(0, false); 512]) });
    let a = sym.0.as_ptr() as usize;
    let slot = (a >> 3 ^ a >> 12) & 511;
    let (k, v) = C.with(|c| {
        let c: &std::cell::Cell<[_]> = c;
        c.as_slice_of_cells()[slot].get()
    });
    if k == a {
        return v;
    }
    let v = read_special(sym.0);
    C.with(|c| {
        let c: &std::cell::Cell<[_]> = c;
        c.as_slice_of_cells()[slot].set((a, v));
    });
    v
}

fn model_prop_sym(sym: Sym) -> bool {
    thread_local!(static C: std::cell::Cell<[(usize, bool); 512]> =
        const { std::cell::Cell::new([(0, false); 512]) });
    let a = sym.0.as_ptr() as usize;
    let slot = (a >> 3 ^ a >> 12) & 511;
    let (k, v) = C.with(|c| {
        let c: &std::cell::Cell<[_]> = c;
        c.as_slice_of_cells()[slot].get()
    });
    if k == a {
        return v;
    }
    let v = crate::types::maybe_model_prop(sym.0);
    C.with(|c| {
        let c: &std::cell::Cell<[_]> = c;
        c.as_slice_of_cells()[slot].set((a, v));
    });
    v
}

/// Names `World::read_inner` resolves specially before the plain property lookup.
fn read_special(name: &str) -> bool {
    matches!(
        name,
        "position"
            | "visualPosition"
            | "origin"
            | "axis"
            | "QsWindow"
            | "devicePixelRatio"
            | "spacing"
            | "rowSpacing"
            | "columnSpacing"
            | "ListView"
            | "GridView"
            | "contentItem"
            | "contentChildren"
            | "screen"
            | "childrenRect"
            | "antialiasing"
            | "topLeftRadius"
            | "topRightRadius"
            | "bottomLeftRadius"
            | "bottomRightRadius"
            | "displayText"
            | "resources"
            | "data"
            | "flickableData"
            | "flickableChildren"
            | "currentText"
            | "currentValue"
            | "mirrored"
            | "count"
            | "currentItem"
            | "delegateModel"
            | "environment"
            | "parent"
            | "margins"
            | "leftMargin"
            | "rightMargin"
            | "topMargin"
            | "bottomMargin"
            | "anchors.leftMargin"
            | "anchors.rightMargin"
            | "anchors.topMargin"
            | "anchors.bottomMargin"
            | "Layout.leftMargin"
            | "Layout.rightMargin"
            | "Layout.topMargin"
            | "Layout.bottomMargin"
            | "children"
            | "visibleChildren"
            // PADDINGS
            | "padding"
            | "horizontalPadding"
            | "verticalPadding"
            | "leftPadding"
            | "rightPadding"
            | "topPadding"
            | "bottomPadding"
            // ANCHOR_LINES
            | "left"
            | "right"
            | "top"
            | "bottom"
            | "horizontalCenter"
            | "verticalCenter"
            | "baseline"
    )
}

/// The wider properties a padding or a margin follows while it is not a set one, nearest
/// first: QQuickControlPrivate::getLeftPadding and those of the positioners and the text
/// items, QQuickPopup::leftMargin (`popup`), QQuickAnchors::leftMargin,
/// QQuickLayoutAttached::leftMargin.
fn wider_of(name: &str, popup: bool) -> &'static [&'static str] {
    match name {
        "leftPadding" | "rightPadding" => &["horizontalPadding", "padding"],
        "topPadding" | "bottomPadding" => &["verticalPadding", "padding"],
        "horizontalPadding" | "verticalPadding" => &["padding"],
        "leftMargin" | "rightMargin" | "topMargin" | "bottomMargin" if popup => &["margins"],
        "anchors.leftMargin"
        | "anchors.rightMargin"
        | "anchors.topMargin"
        | "anchors.bottomMargin" => &["anchors.margins"],
        "Layout.leftMargin" | "Layout.rightMargin" | "Layout.topMargin" | "Layout.bottomMargin" => {
            &["Layout.margins"]
        }
        _ => &[],
    }
}

/// ProxyWindowBase::setWidth and setHeight set the implicit size: `width` and `height` only
/// read the window's size.
fn window_size_setter(name: &str) -> Option<&'static str> {
    match name {
        "width" => Some("implicitWidth"),
        "height" => Some("implicitHeight"),
        _ => None,
    }
}

impl World {
    /// The property a QML assignment to `name` of `item` sets: a PanelWindow's `width` and
    /// `height` set its implicit size, which Quickshell warns is deprecated.
    fn assigned_name<'a>(&self, item: usize, name: &'a str) -> &'a str {
        let Some(to) = window_size_setter(name) else {
            return name;
        };
        if !self.items[item].types.iter().any(|t| t == "PanelWindow") {
            return name;
        }
        tracing::warn!(
            target: "ri::qml",
            "QML PanelWindow: Setting `{name}` is deprecated. Set `{to}` instead."
        );
        to
    }
}

/// Some declared property is `name.<sub>` (a grouped property). The per-item prefix hashes are
/// rebuilt only when properties were added; a hash hit is confirmed against the keys.
fn has_group_key(inst: &Inst, name: &str) -> bool {
    let props = &inst.props;
    let mut e = inst.group_prefixes.borrow_mut();
    if e.0 != props.len() {
        e.1.clear();
        for k in props.keys() {
            for (i, _) in k.match_indices('.') {
                e.1.push(prefix_hash(&k[..i]));
            }
        }
        e.1.sort_unstable();
        e.1.dedup();
        e.0 = props.len();
    }
    if e.1.is_empty() {
        return false;
    }
    let n = name.len();
    e.1.binary_search(&prefix_hash(name)).is_ok()
        && props
            .keys()
            .any(|k| k.len() > n && k.as_bytes()[n] == b'.' && k.starts_with(name))
}

impl World {
    /// Whether some declared/assigned property of `item` is grouped under `name` (`name.x`).
    pub fn has_grouped(&mut self, item: usize, name: &str) -> bool {
        let Some(inst) = self.items.get(item) else {
            return false;
        };
        has_group_key(inst, name)
    }
}

impl Inst {
    /// The name of the object's class: the one its declaration got ([`Self::class`]), else its
    /// type's C++ class.
    pub fn class_name(&self) -> String {
        if let Some(c) = self.class {
            return c.to_string();
        }
        let r = crate::types::registry();
        match self.types.first() {
            // `T.Button`: the type its qualifier is in front of.
            Some(t) => match (r.resolve(t)).or_else(|| r.resolve(t.as_str().rsplit_once('.')?.1)) {
                Some((_, ti)) => ti.cpp.to_string(),
                None if matches!(t.as_str(), "ListViewAttached" | "GridViewAttached") => {
                    format!("QQuick{t}")
                }
                // QQuickFlickable::contentItem is a plain item.
                None if t.as_str() == "\x01contentItem" => "QQuickItem".to_string(),
                None => format!("{t}_QMLTYPE_0"),
            },
            None => "QObject".to_string(),
        }
    }

    /// What a destroyed instance reads as.
    fn dead() -> Inst {
        Inst {
            types: vec![Sym::new("\x01dead")],
            ..Default::default()
        }
    }
    pub fn has_handler(&self, name: &str) -> bool {
        Sym::lookup(name).is_some_and(|h| self.handlers.contains_key(&h))
    }
    pub fn prop_info(&self, name: &str) -> Option<&'static crate::types::PropInfo> {
        // No C++ type declares a property of a name the registry does not list: such a name
        // is not interned for the lookup.
        let sym = Sym::lookup(name).or_else(|| {
            crate::types::registry()
                .prop_names
                .contains_key(name)
                .then(|| Sym::new(name))
        })?;
        self.prop_info_sym(sym)
    }
    /// Whether property `name` is one QQmlEnumTypeResolver assigns enum references to as
    /// constants: an enum or an `int`, declared or C++.
    pub fn enum_target(&self, name: Sym) -> bool {
        match self.prop_info_sym(name) {
            Some(pi) => pi.enumeration || pi.ty == "int",
            None => self.props.get_sym(name).is_some_and(|p| &*p.ty == "int"),
        }
    }
    /// Whether a JavaScript write to `name` is refused, as QV4's QObjectWrapper::setProperty
    /// refuses a property that is not writable: a QML `readonly property`, or a C++ property
    /// without a WRITE accessor, except a QQmlListProperty (assigned by clear + append).
    pub fn read_only(&self, name: Sym) -> bool {
        match self.props.get_sym(name).map(|p| p.decl) {
            Some(Decl::ReadOnly) => true,
            Some(Decl::Writable) => false,
            Some(Decl::Cpp) | None => self
                .prop_info_sym(name)
                .is_some_and(|p| p.readonly && !p.list),
        }
    }
    pub fn prop_info_sym(&self, name: Sym) -> Option<&'static crate::types::PropInfo> {
        let mut s = self.tset.get();
        if s == 0 {
            s = crate::types::type_set(&self.types);
            self.tset.set(s);
        }
        crate::types::find_prop_in_sym(s, &self.types, name)
    }

    /// QML `instanceof` with a type name: see `types::inherits_in`.
    pub fn inherits(&self, name: &str) -> bool {
        let mut s = self.tset.get();
        if s == 0 {
            s = crate::types::type_set(&self.types);
            self.tset.set(s);
        }
        crate::types::inherits_in(s, &self.types, Sym::new(name))
    }
}

/// Marks the Flickable and the ScrollBars a ScrollView made itself.
pub const SCROLL_MADE: &str = "\x01scrollMade";

/// The attached bars of a Flickable or a ScrollView, and whether each is the vertical one.
pub const SCROLL_BARS: [(&str, bool); 2] = [
    ("ScrollBar.vertical", true),
    ("ScrollBar.horizontal", false),
];

/// Marks an object that declares `function onLengthChanged` before `function onTextChanged`.
const LENGTH_FIRST: &str = "\x01lengthFirst";

/// One member of an object where its document writes it: `m`, bound under `name` at this
/// level (`pixelSize` for `font.pixelSize` among the bindings of `font`).
#[derive(Clone, Copy)]
struct Row<'a> {
    m: &'a Member,
    name: &'a str,
    /// Written inside `name { … }`, not as `name.…: …`.
    braced: bool,
}

impl<'a> Row<'a> {
    fn of(m: &'a Member, braced: bool) -> Self {
        let name = match m {
            Member::Binding { name, .. } => name.as_str(),
            _ => "",
        };
        Row { m, name, braced }
    }
}

/// A row of an object's binding table: one member, or all the bindings of one attached or
/// group property.
enum Entry<'a> {
    Row(Row<'a>),
    Sub(&'a str, Vec<Row<'a>>),
}

fn is_function(v: &Value) -> bool {
    matches!(v, Value::Obj(o) if o.borrow().call.is_some())
}

/// QQuickTextEdit and the control built on it.
fn is_text_edit(types: &[Sym]) -> bool {
    types
        .iter()
        .any(|t| matches!(t.as_str(), "TextEdit" | "TextArea"))
}

