    /// `Animation on prop` is a property value source: with no target/property of its own it
    /// animates `prop` of the object it is declared in (an Animator: its target defaults to it).
    #[test]
    fn value_source_animation_drives_its_property() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    property alias r: r
    Rectangle {
        id: r
        width: 10; height: 10
        RotationAnimation on rotation { running: true; duration: 1000; loops: Animation.Infinite; from: 360; to: 0 }
        NumberAnimation on x { running: true; duration: 1000; from: 0; to: 100 }
        YAnimator on y { running: true; duration: 1000; from: 0; to: 40 }
        SequentialAnimation on opacity {
            running: true
            NumberAnimation { from: 1; to: 0.5; duration: 500 }
            NumberAnimation { from: 0.5; to: 1; duration: 500 }
        }
    }
}"#,
            )
            .unwrap();
        rt.settle();
        let Value::Item(r) = rt.get(root, "r") else {
            panic!("no r")
        };
        rt.tick(0.0);
        rt.tick(250.0);
        rt.settle();
        let n = |rt: &Runtime, k: &str| rt.get(r, k).to_number();
        assert!(
            (n(&rt, "rotation") - 270.0).abs() < 1.0,
            "rotation {}",
            n(&rt, "rotation")
        );
        assert!((n(&rt, "x") - 25.0).abs() < 1.0, "x {}", n(&rt, "x"));
        assert!((n(&rt, "y") - 10.0).abs() < 1.0, "y {}", n(&rt, "y"));
        assert!(
            (n(&rt, "opacity") - 0.75).abs() < 0.01,
            "opacity {}",
            n(&rt, "opacity")
        );
    }

    /// Qt5Compat effects are Items: rotating a DropShadow (the cookie clock's
