    #[test]
    fn swipe_highlight_move_eases_like_qsmoothedanimation() {
        // 200 px at highlightMoveVelocity 400 would take 500 ms: highlightMoveDuration caps it
        // at 250 ms, accelerating for half of it and decelerating for the rest.
        let mut a = SmoothedAnimation::default();
        a.target(0.0, 200.0, 1000.0);
        assert!(a.running());
        assert_eq!(a.value(1000.0), 0.0);
        assert!((a.value(1062.5) - 25.0).abs() < 1e-9);
        assert!((a.value(1125.0) - 100.0).abs() < 1e-9);
        assert!((a.value(1187.5) - 175.0).abs() < 1e-9);
        assert_eq!(a.value(1250.0), 200.0);
        assert!(!a.running());
        // Short moves run at the velocity: 40 px take 100 ms.
        a.target(200.0, 160.0, 0.0);
        assert!((a.value(50.0) - 180.0).abs() < 1e-9);
        assert_eq!(a.value(100.0), 160.0);
        // A retarget mid-move keeps the speed: reversing first decelerates past the turn point.
        a.target(0.0, 400.0, 0.0);
        let mid = a.value(125.0);
        a.target(mid, 0.0, 125.0);
        assert!(a.value(140.0) > mid);
        assert_eq!(a.value(10_000.0), 0.0);
    }

    #[test]
    fn unqualified_write_reaches_cpp_property_not_global() {
        // QV4: the global object is frozen; `source = x` in a Loader handler sets Loader.source.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property string got: \"\"\n property var ls\n Loader { id: l\n Component.onCompleted: { source = \"Nope.qml\" } }\n Item { Component.onCompleted: { got = typeof source; ls = l.source } }\n}\n",
            )
            .unwrap();
        rt.settle();
        let r = |n: &str| {
            rt.world
                .borrow_mut()
                .read(root, n)
                .map(|v| v.to_js_string())
        };
        assert_eq!(r("got").as_deref(), Some("undefined"));
        // Qt 6.12: the later sibling's onCompleted runs first, before the Loader's write.
        assert_eq!(r("ls").as_deref(), Some(""));
        let l = rt.world.borrow_mut().of_type("Loader")[0];
        assert!(rt.get(l, "source").to_js_string().ends_with("Nope.qml"));
    }

    #[test]
    fn watchdog_interrupts_runaway_handlers_and_sync_bindings() {
        use std::time::Duration;
        crate::watchdog::set_timeout(Some(Duration::from_millis(200)));
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property int n: 0\n property int spin: 0\n property int d: { if (spin > 0) for (;;) {} return n }\n property int after: 0\n function go() { spin = 1; after = d + 1 }\n onNChanged: { if (n === 2) for (;;) {} after = 7 }\n}\n",
            )
            .unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        // Short evaluations, however many, are never interrupted: together they take 2.5 times
        // the timeout of this thread's CPU time, which the timeout counts.
        let cpu = crate::watchdog::thread_cpu_time;
        let t0 = cpu();
        let mut k = 0;
        while cpu() - t0 < Duration::from_millis(500) {
            k += 1;
            rt.set(root, "n", Value::Num(if k % 2 == 0 { 1.0 } else { 3.0 }));
        }
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        // A runaway handler is interrupted and the runtime goes on.
        rt.set(root, "after", Value::Num(0.0));
        let t0 = cpu();
        rt.set(root, "n", Value::Num(2.0));
        assert!(cpu() - t0 < Duration::from_secs(2));
        assert_eq!(rt.get(root, "after").to_number(), 0.0);
        let errs = rt.errors();
        assert!(
            errs.iter().any(|e| e.ends_with("onNChanged: Interrupted")),
            "{errs:?}"
        );
        rt.set(root, "n", Value::Num(5.0));
        assert_eq!(rt.get(root, "after").to_number(), 7.0);
        // A binding a JS write re-evaluates synchronously is part of the writer's evaluation.
        let t0 = cpu();
        let _ = rt.call_method(root, "go", vec![]);
        assert!(cpu() - t0 < Duration::from_secs(2));
        let errs = rt.errors();
        assert!(errs.iter().any(|e| e.contains("Interrupted")), "{errs:?}");
        assert_eq!(crate::eval::js_depth(), 0);
        crate::watchdog::set_timeout(Some(crate::watchdog::DEFAULT_TIMEOUT));
    }

    #[test]
    fn step_budget_interrupts_runaways_at_the_same_point_every_run() {
        crate::watchdog::set_timeout(None);
        crate::watchdog::set_step_budget(Some(10_000));
        let run = || {
            let mut rt = Runtime::new(None);
            let root = rt
                .load_str(
                    "import QtQuick\nItem {\n property int k: 0\n property int n: 0\n property int m: 0\n onNChanged: { var i = 0; for (;;) { i++; k = i } }\n onMChanged: k = -1\n}\n",
                )
                .unwrap();
            rt.settle();
            rt.set(root, "n", Value::Num(1.0));
            let reached = rt.get(root, "k").to_number();
            let errs = rt.errors();
            assert!(
                errs.iter().any(|e| e.ends_with("onNChanged: Interrupted")),
                "{errs:?}"
            );
            // The next evaluation starts with a fresh budget.
            rt.set(root, "m", Value::Num(1.0));
            assert_eq!(rt.get(root, "k").to_number(), -1.0);
            reached
        };
        let a = run();
        assert!(a > 0.0);
        assert_eq!(run(), a);
        assert_eq!(crate::watchdog::take_exhausted(), 2);
        assert_eq!(crate::eval::js_depth(), 0);
        crate::watchdog::set_step_budget(None);
        crate::watchdog::set_timeout(Some(crate::watchdog::DEFAULT_TIMEOUT));
    }

    #[test]
    fn nested_change_handlers_reuse_builtins() {
        // A change handler writing another handled property re-enters fire_sync while the
        // side interpreter is taken: the nested one shares the global scope instead of
        // installing the builtins again for every write (2000 writes took 225 ms, not 1 ms).
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property int a: 0\n property int b: 0\n property int c: 0\n property bool go: false\n onGoChanged: { for (let i = 1; i <= 2000; i++) a = i }\n onAChanged: b = a\n onBChanged: c += 1\n}\n",
            )
            .unwrap();
        rt.settle();
        let before = crate::builtins::INSTALLS.with(|c| c.get());
        rt.set(root, "go", Value::Bool(true));
        rt.settle();
        let installs = crate::builtins::INSTALLS.with(|c| c.get()) - before;
        let r = |n: &str| rt.world.borrow_mut().read(root, n).map(|v| v.to_number());
        assert_eq!(r("b"), Some(2000.0));
        assert_eq!(r("c"), Some(2000.0));
        assert_eq!(installs, 0);
    }

    #[test]
