    #[test]
    fn canvas_style_state_follows_qt_setters() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property real w: -1.5\n property color col: \"#8d868d\"\n Canvas { id: c\n width: w\n height: 36\n onPaint: { var ctx = getContext(\"2d\"); ctx.clearRect(0, 0, width, height); ctx.strokeStyle = col; ctx.fillStyle = \"#102030\"; ctx.lineWidth = 4; ctx.lineCap = \"round\"; ctx.beginPath(); ctx.moveTo(1, 1); ctx.lineTo(9, 9); ctx.stroke() } }\n property var cv: c\n}\n",
            )
            .unwrap();
        rt.settle();
        rt.canvases_available();
        rt.settle();
        rt.world.borrow_mut().write(root, "w", Value::Num(98.5));
        rt.settle();
        let c = match rt.world.borrow_mut().read(root, "cv") {
            Some(Value::Item(i)) => i,
            v => panic!("{v:?}"),
        };
        let ops = format!("{:?}", rt.world.borrow().canvas_ops[&c]);
        // The empty first window dropped the string/number state; only the QColor value is
        // re-recorded on every assignment, so the stroke keeps Qt's default width and cap.
        assert!(ops.contains("SetStroke(Color("), "{ops}");
        assert!(!ops.contains("SetFill"), "{ops}");
        assert!(!ops.contains("SetLineWidth"), "{ops}");
        assert!(!ops.contains("SetCap"), "{ops}");
        assert!(ops.contains("Stroke(["), "{ops}");
    }

