    #[test]
    fn content_children_follow_deps_and_replace_pages() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nimport QtQuick.Controls\nItem {\n property bool flag: true\n SwipeView {\n id: sv\n contentChildren: [\n ...(flag ? [a.createObject()] : []),\n b.createObject(),\n ]\n }\n Component { id: a\n Item {} }\n Component { id: b\n Item {} }\n property var view: sv\n}\n",
            )
            .unwrap();
        rt.settle();
        let sv = match rt.world.borrow_mut().read(root, "view") {
            Some(Value::Item(i)) => i,
            v => panic!("{v:?}"),
        };
        let pages = |rt: &Runtime| rt.world.borrow().items[sv].children.clone();
        let before = pages(&rt);
        assert_eq!(before.len(), 2);
        rt.world
            .borrow_mut()
            .write(root, "flag", Value::Bool(false));
        rt.settle();
        assert_eq!(pages(&rt).len(), 1);
        rt.world.borrow_mut().write(root, "flag", Value::Bool(true));
        rt.settle();
        let before = pages(&rt);
        assert_eq!(before.len(), 2);
        assert!(before.iter().all(|c| !rt.world.borrow().dead.contains(c)));
        // Reassigning the list replaces (destroys) the previous pages.
        let mut w = rt.world.borrow_mut();
        let keep = before[1];
        w.write(sv, "contentChildren", Value::array(vec![Value::Item(keep)]));
        assert!(w.dead.contains(&before[0]));
        assert!(!w.dead.contains(&keep));
    }

