    #[test]
    fn singleton_named_only_in_handlers_is_created_on_first_use() {
        let d = std::env::temp_dir().join(format!("qml-lazy-single-{}", std::process::id()));
        let sv = d.join("services");
        std::fs::create_dir_all(&sv).unwrap();
        std::fs::write(
            sv.join("Eager.qml"),
            "pragma Singleton\nimport QtQuick\nQtObject { property int hits: 0 }\n",
        )
        .unwrap();
        std::fs::write(
            sv.join("Lazy.qml"),
            "pragma Singleton\nimport QtQuick\nimport ri.services\nQtObject { property int n: 7\n Component.onCompleted: Eager.hits += 1 }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            "import QtQuick\nimport ri.services\nItem { property int e: Eager.hits\n property int got: 0\n property bool go: false\n onGoChanged: got = Lazy.n }\n",
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.clone()));
        rt.load_singletons_lazy(std::slice::from_ref(&sv));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        assert!(rt.world.borrow().singletons.contains_key("Eager"));
        assert!(!rt.world.borrow().singletons.contains_key("Lazy"));
        assert_eq!(rt.get(root, "e").to_js_string(), "0");
        rt.set(root, "go", Value::Bool(true));
        rt.settle();
        assert_eq!(rt.get(root, "got").to_js_string(), "7");
        assert_eq!(rt.get(root, "e").to_js_string(), "1");
        let errs: Vec<String> = rt.world.borrow().errors.clone();
        assert!(errs.is_empty(), "{errs:?}");
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn compiled_name_read_creates_lazy_singleton() {
        // AOT bodies read free names through `Interp::host_lookup`, not `Interp::lookup`.
        let d = std::env::temp_dir().join(format!("qml-lazy-aot-{}", std::process::id()));
        let sv = d.join("services");
        std::fs::create_dir_all(&sv).unwrap();
        std::fs::write(
            sv.join("Lazy.qml"),
            "pragma Singleton\nimport QtQuick\nQtObject { property int n: 7 }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            "import QtQuick\nimport ri.services\nItem { onWidthChanged: console.log(Lazy.n) }\n",
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.clone()));
        rt.load_singletons_lazy(std::slice::from_ref(&sv));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        assert!(!rt.world.borrow().singletons.contains_key("Lazy"));
        let ctx = rt.world.borrow().items[root]
            .handlers
            .values()
            .next()
            .unwrap()[0]
            .ctx;
        let v = rt.it.host_lookup(Some((root, ctx)), "Lazy");
        assert!(matches!(v, Some(Value::Item(_))), "{v:?}");
        let id = rt.world.borrow().singletons["Lazy"];
        assert_eq!(rt.get(id, "n").to_js_string(), "7");
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn lazy_singleton_builds_its_own_loaders_not_the_callers() {
        // OnScreenKeyboard's `active: GlobalStates.oskOpen` emits activeChanged at creation and
        // its handler names Ydotool: the singleton is created with its own Loader's item, while
        // a Loader of the shell still pending loads in the shell's own pass, not inside it.
        let d = std::env::temp_dir().join(format!("qml-lazy-deleg-{}", std::process::id()));
        let sv = d.join("services");
        std::fs::create_dir_all(&sv).unwrap();
        std::fs::write(
            sv.join("Lazy.qml"),
            "pragma Singleton\nimport QtQuick\nItem {\n property int n: inner.item ? inner.item.v : -1\n Loader { id: inner; sourceComponent: QtObject { property int v: 3 } }\n}\n",
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            r#"import QtQuick
import ri.services
Item {
    id: root
    property bool on: false
    property string out: ""
    property int built: 0
    Loader {
        active: root.on
        onActiveChanged: root.out += "n:" + Lazy.n + "/built:" + root.built + ";"
        sourceComponent: Item {}
    }
    Loader {
        sourceComponent: Repeater { model: 50; Item { Component.onCompleted: root.built++ } }
    }
}"#,
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.clone()));
        rt.load_singletons_lazy(std::slice::from_ref(&sv));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        let errs: Vec<String> = rt.world.borrow().errors.clone();
        assert!(errs.is_empty(), "{errs:?}");
        assert_eq!(rt.get(root, "out").to_js_string(), "n:3/built:0;");
        assert_eq!(rt.get(root, "built").to_js_string(), "50");
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn lazy_singleton_handler_write_leaves_the_callers_loaders_pending() {
        // A handler the singleton's creation runs writes a property: QQuickLoader loads inside
        // that write only once it is complete, and the caller's Loaders mid-creation are not
        // (SidebarRightContent's classic quick panel, off by its `active` binding, must never
        // be built: its GameMode toggle would query Hyprland).
        let d = std::env::temp_dir().join(format!("qml-lazy-pending-{}", std::process::id()));
        let sv = d.join("services");
        std::fs::create_dir_all(&sv).unwrap();
        std::fs::write(
            sv.join("Lazy.qml"),
            "pragma Singleton\nimport QtQuick\nQtObject { property int n: 0\n Component.onCompleted: n = 7 }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("Sub.qml"),
            "import QtQuick\nimport ri.services\nItem { property int k: Lazy.n }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            r#"import QtQuick
Item {
    id: root
    property string style: "android"
    property int made: 0
    property alias k: sub.k
    Item {
        Impl { styleName: "classic"; sourceComponent: Item { Component.onCompleted: root.made++ } }
        Sub { id: sub }
    }
    component Impl: Loader {
        property string styleName
        active: root.style === styleName
    }
}"#,
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.clone()));
        rt.load_singletons_lazy(std::slice::from_ref(&sv));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        let errs: Vec<String> = rt.world.borrow().errors.clone();
        assert!(errs.is_empty(), "{errs:?}");
        assert_eq!(rt.get(root, "k").to_js_string(), "7");
        assert_eq!(rt.get(root, "made").to_js_string(), "0");
        rt.set(root, "style", Value::Str("classic".into()));
        rt.settle();
        assert_eq!(rt.get(root, "made").to_js_string(), "1");
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn lazy_singleton_named_by_a_handler_keeps_the_handlers_closed_loader_item() {
        // A handler closes the Loader it lives in and then names a singleton nothing created
        // yet (`root.open = false; root.out = "n:" + Lazy.n + ...`).
        // QObject::deleteLater waits for the event loop, so the rest of the handler still
        // sees its ids.
        let d = std::env::temp_dir().join(format!("qml-lazy-doomed-{}", std::process::id()));
        let sv = d.join("services");
        std::fs::create_dir_all(&sv).unwrap();
        std::fs::write(
            sv.join("Lazy.qml"),
            "pragma Singleton\nimport QtQuick\nQtObject { property int n: 0\n Component.onCompleted: n = 7 }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            r#"import QtQuick
import ri.services
Item {
    id: root
    property bool open: true
    property string tag: "x"
    property string out: ""
    property bool closed: menu.item === null
    function act() { menu.item.hit() }
    Loader {
        id: menu
        active: root.open
        sourceComponent: Item {
            signal hit()
            onHit: {
                root.open = false;
                root.out = "n:" + Lazy.n + "/" + root.tag;
            }
        }
    }
}"#,
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.clone()));
        rt.load_singletons_lazy(std::slice::from_ref(&sv));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        rt.call_method(root, "act", vec![]).unwrap().unwrap();
        rt.settle();
        let errs: Vec<String> = rt.world.borrow().errors.clone();
        assert!(errs.is_empty(), "{errs:?}");
        assert_eq!(rt.get(root, "out").to_js_string(), "n:7/x");
        assert_eq!(rt.get(root, "closed").to_js_string(), "true");
        let _ = std::fs::remove_dir_all(&d);
    }

