    #[test]
    fn three_level_binding_order() {
        let d = std::env::temp_dir().join(format!("qml-three-{}", std::process::id()));
        std::fs::create_dir_all(&d).unwrap();
        std::fs::write(
            d.join("Base.qml"),
            "import QtQuick\nItem { property var rp: null\n property var bounds: rp.b\n property var morph: rp.foo\n onRpChanged: { morph = rp.foo }\n }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("Shape.qml"),
            "import QtQuick\nBase { id: root\n required property var shape\n property real size\n implicitWidth: size\n rp: { switch (root.shape) { case 1: return { foo: 7, b: 1 }; default: return { foo: 1, b: 1 } } } }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("Wrapped.qml"),
            "import QtQuick\nShape { id: root\n property alias text: t.text\n shape: 1\n size: t.implicitWidth + 2\n Text { id: t } }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("Host.qml"),
            "import QtQuick\nItem { property Item contentItem\n Item { id: holder; data: [contentItem] } }\n",
        )
        .unwrap();
        std::fs::write(
            d.join("Cc.qml"),
            "import QtQuick\nItem { id: root\n property var map: ({ \"c\": \"color\" })\n property var code: root.parent ? root.parent.width : 0\n property string got: \"\"\n function reload() { got = root.map[\"c\"] }\n Component.onCompleted: reload()\n onCodeChanged: reload()\n}\n",
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            "import QtQuick\nItem { Wrapped { id: s; text: \"x\" }\n Host { id: h; contentItem: Cc { id: cc; anchors.centerIn: parent } }\n property var got: s.morph\n property string got2: cc.got\n }\n",
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.clone()));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        let errs: Vec<String> = rt.world.borrow().errors.clone();
        assert!(errs.is_empty(), "{errs:?}");
        assert_eq!(rt.get(root, "got").to_number(), 7.0);
        assert_eq!(rt.get(root, "got2").to_js_string(), "color");
    }

