    #[test]
    fn combo_box_complete_and_highlight() {
        let d = std::env::temp_dir().join(format!("qml-combo-hl-{}", std::process::id()));
        std::fs::create_dir_all(&d).unwrap();
        std::fs::write(
            d.join("main.qml"),
            r#"import QtQuick
                import QtQuick.Controls
                Item {
                    id: root
                    property string log: ""
                    property alias box: cb
                    ComboBox {
                        id: cb
                        model: ["a", "b", "c"]
                        onCurrentIndexChanged: root.log += "i" + currentIndex
                        onDisplayTextChanged: root.log += "t" + displayText
                        onHighlightedIndexChanged: root.log += "h" + highlightedIndex
                        delegate: ItemDelegate { required property int index; width: 100; height: 40 }
                        popup: Popup {
                            onVisibleChanged: root.log += "v" + visible
                            contentItem: ListView { model: cb.delegateModel; implicitHeight: 120 }
                        }
                    }
                    ComboBox { id: fixed; model: ["x", "y"]; currentIndex: -1 }
                    ComboBox { id: empty; model: [] }
                    property int f: fixed.currentIndex
                    property int e: empty.currentIndex
                }"#,
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.clone()));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        // QQuickComboBox::componentComplete: -1 -> 0 only without an explicit currentIndex.
        assert_eq!(rt.get(root, "log").to_js_string(), "i0ta");
        assert_eq!(rt.get(root, "f").to_number(), -1.0);
        assert_eq!(rt.get(root, "e").to_number(), -1.0);
        let Value::Item(cb) = rt.get(root, "box") else {
            panic!("no box")
        };
        let Value::Item(pop) = rt.get(cb, "popup") else {
            panic!("no popup")
        };
        rt.set(root, "log", Value::str(""));
        rt.world.borrow_mut().popup_set_visible(pop, true);
        rt.settle();
        assert_eq!(rt.get(root, "log").to_js_string(), "vtrueh0");
        let ds = rt.world.borrow_mut().of_type("ItemDelegate");
        assert_eq!(ds.len(), 3);
        rt.world
            .borrow_mut()
            .write(ds[2], "hovered", Value::Bool(true));
        rt.settle();
        assert_eq!(rt.get(cb, "highlightedIndex").to_number(), 2.0);
        rt.set(root, "log", Value::str(""));
        rt.world
            .borrow_mut()
            .write(pop, "visible", Value::Bool(false));
        rt.settle();
        assert_eq!(rt.get(root, "log").to_js_string(), "vfalseh-1");
        let _ = std::fs::remove_dir_all(&d);
    }

