    #[test]
    fn stack_view_push_pop() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
                import QtQuick.Controls
                Item {
                    id: root
                    property int acts: 0
                    property int removed: 0
                    Component { id: comp; Item { implicitWidth: 70; StackView.onActivating: root.acts++; StackView.onRemoved: { root.removed++; destroy() } } }
                    StackView {
                        id: sv
                        implicitWidth: currentItem.implicitWidth
                        initialItem: Item { implicitWidth: 40; StackView.onActivating: root.acts++ }
                    }
                    property alias sv: sv
                    property int w: sv.implicitWidth
                    property int d: sv.depth
                    signal go()
                    signal back()
                    onGo: sv.push(comp.createObject(null))
                    onBack: sv.pop()
                }"#,
            )
            .unwrap();
        // Like Qt, currentItem is null until componentComplete pushes initialItem, which
        // becomes Active without passing Activating. Qt 6.12 prints (w, d, acts, removed):
        // 40 1 0 0 after load, 70 2 1 0 after the push, 40 1 2 1 after the pop.
        assert_eq!(rt.get(root, "w").to_number(), 40.0);
        assert_eq!(rt.get(root, "d").to_number(), 1.0);
        assert_eq!(rt.get(root, "acts").to_number(), 0.0);
        rt.emit(root, "go", &[], vec![]);
        rt.settle();
        assert_eq!(rt.get(root, "w").to_number(), 70.0);
        assert_eq!(rt.get(root, "d").to_number(), 2.0);
        assert_eq!(rt.get(root, "acts").to_number(), 1.0);
        rt.emit(root, "back", &[], vec![]);
        rt.settle();
        assert_eq!(rt.get(root, "w").to_number(), 40.0);
        assert_eq!(rt.get(root, "removed").to_number(), 1.0);
        assert_eq!(rt.get(root, "acts").to_number(), 2.0);
    }

    /// QQuickStackView::push(item, properties, operation): "item can be an Item, Component, or
    /// a url". A Component is created as the view's child, with the properties given after it,
    /// and deleted when popped (QQuickStackElement::ownsItem).
    #[test]
    fn stack_view_push_creates_a_component() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
                import QtQuick.Controls
                Item {
                    id: root
                    property int destroyed: 0
                    property Component page: Component {
                        Item {
                            property string title: "none"
                            implicitWidth: 70
                            Component.onDestruction: root.destroyed++
                        }
                    }
                    StackView {
                        id: sv
                        initialItem: Item { implicitWidth: 40 }
                    }
                    property int d: sv.depth
                    property int w: sv.currentItem.implicitWidth
                    property string title: sv.currentItem.title ?? ""
                    property bool childOfView: sv.currentItem.parent === sv
                    property var pushed: null
                    function go() { pushed = sv.push(root.page) }
                    function goWith() { sv.push(root.page, { title: "wifi" }, StackView.Immediate) }
                    function back() { sv.pop() }
                }"#,
            )
            .unwrap();
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.settle();
        assert_eq!(rt.get(root, "d").to_number(), 2.0);
        assert_eq!(
            rt.get(root, "w").to_number(),
            70.0,
            "an instance, not the Component"
        );
        assert!(rt.get(root, "childOfView").truthy());
        assert_eq!(rt.get(root, "title").to_js_string(), "none");
        let Value::Item(first) = rt.get(root, "pushed") else {
            panic!("push returns the item it created");
        };
        rt.call_method(root, "goWith", vec![]).unwrap().unwrap();
        rt.settle();
        assert_eq!(rt.get(root, "d").to_number(), 3.0);
        assert_eq!(rt.get(root, "title").to_js_string(), "wifi");
        rt.call_method(root, "back", vec![]).unwrap().unwrap();
        rt.settle();
        rt.call_method(root, "back", vec![]).unwrap().unwrap();
        rt.settle();
        assert_eq!(rt.get(root, "d").to_number(), 1.0);
        // QObject::deleteLater: the popped items go once the event loop runs again.
        assert_eq!(rt.get(root, "destroyed").to_number(), 0.0);
        rt.tick(1.0);
        rt.settle();
        assert_eq!(rt.get(root, "destroyed").to_number(), 2.0);
        assert!(rt.world.borrow().dead.contains(&first));
        assert_eq!(rt.errors(), Vec::<String>::new());
    }

