    #[test]
    fn delegators_follow_inputs_after_unrelated_changes() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"Item {
                    id: root
                    property int noise: 0
                    property int n: 2
                    property bool useB: false
                    property bool on: false
                    property string log: ""
                    Component { id: ca; Item { Component.onCompleted: root.log += "a" } }
                    Component { id: cb; Item { Component.onCompleted: root.log += "b" } }
                    Repeater { id: r; model: root.n; delegate: root.useB ? cb : ca }
                    Loader { id: l; active: root.on; sourceComponent: ca }
                    property int rc: r.count
                    property bool loaded: l.item !== null
                }"#,
            )
            .unwrap();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        for k in 0..3 {
            rt.set(root, "noise", Value::Num(k as f64));
        }
        assert_eq!(rt.get(root, "rc").to_number(), 2.0);
        rt.set(root, "n", Value::Num(3.0));
        assert_eq!(rt.get(root, "rc").to_number(), 3.0);
        rt.set(root, "noise", Value::Num(9.0));
        rt.set(root, "useB", Value::Bool(true));
        assert!(rt.get(root, "log").to_js_string().ends_with("bbb"));
        assert!(!rt.get(root, "loaded").truthy());
        rt.set(root, "noise", Value::Num(10.0));
        rt.set(root, "on", Value::Bool(true));
        assert!(rt.get(root, "loaded").truthy());
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn sequential_actions_and_running() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"Item {
                    id: root
                    property real x2: 0
                    property int hits: 0
                    property string s: "a"
                    property bool go: false
                    property bool busy: seq.running
                    SequentialAnimation {
                        id: seq
                        running: root.go
                        NumberAnimation { target: root; property: "x2"; to: 10; duration: 100 }
                        PropertyAction { target: root; property: "s"; value: "b" }
                        ScriptAction { script: root.hits++ }
                        PauseAnimation { duration: 50 }
                        onFinished: root.hits += 10
                    }
                    SequentialAnimation {
                        running: true
                        loops: Animation.Infinite
                        PauseAnimation { duration: 10 }
                    }
                }"#,
            )
            .unwrap();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(rt.get(root, "hits").to_number(), 0.0);
        rt.set(root, "go", Value::Bool(true));
        assert!(rt.get(root, "busy").truthy());
        assert!(rt.tick(50.0));
        assert_eq!(rt.get(root, "x2").to_number(), 5.0);
        assert_eq!(rt.get(root, "s").to_js_string(), "a");
        rt.tick(100.0);
        assert_eq!(rt.get(root, "x2").to_number(), 10.0);
        assert_eq!(rt.get(root, "s").to_js_string(), "b");
        assert_eq!(rt.get(root, "hits").to_number(), 1.0);
        rt.tick(149.0);
        assert!(rt.get(root, "busy").truthy());
        assert!(rt.tick(150.0), "infinite loop keeps running");
        assert_eq!(rt.get(root, "hits").to_number(), 11.0);
        assert!(!rt.get(root, "busy").truthy());
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn created_inline_timer_fires() {
        let dir = std::env::temp_dir().join(format!("qml-timer-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let f = dir.join("T.qml");
        std::fs::write(
            &f,
            r#"import QtQuick
                Item {
                    id: root
                    property int hits: 0
                    property list<QtObject> list: []
                    component Notif: QtObject { property Timer timer }
                    component NotifTimer: Timer {
                        required property int notificationId
                        interval: 7000
                        running: true
                        onTriggered: () => { root.hits += notificationId; destroy() }
                    }
                    Component { id: nc; Notif {} }
                    Component { id: tc; NotifTimer {} }
                    function make() {
                        const n = nc.createObject(root, {});
                        root.list = [...root.list, n];
                        n.timer = tc.createObject(root, { "notificationId": 3, "interval": 100 });
                    }
                }"#,
        )
        .unwrap();
        let mut rt = Runtime::new(Some(dir.clone()));
        let root = rt.load_file(&f).unwrap();
        rt.tick(0.0);
        let _ = rt.call_method(root, "make", vec![]).unwrap();
        rt.settle();
        rt.tick(10.0);
        rt.tick(50.0);
        rt.tick(200.0);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(rt.get(root, "hits").to_number(), 3.0);
    }

