    #[test]
    fn states_with_transition_restore_bindings() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"Item {
                    id: root
                    property bool flag: false
                    property real w: 10
                    property real bs: box.size
                    property string st: box.state
                    property real other: box.other
                    Item {
                        id: box
                        property real size: root.w
                        property real other: 1
                        states: State {
                            name: "big"
                            when: root.on
                            PropertyChanges { target: box; size: 100; other: root.w + 1 }
                        }
                        transitions: Transition { NumberAnimation { property: "size"; duration: 100 } }
                    }
                }"#,
            )
            .unwrap();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(rt.get(root, "bs").to_number(), 10.0);
        rt.set(root, "on", Value::Bool(true));
        assert_eq!(rt.get(root, "st").to_js_string(), "big");
        assert_eq!(rt.get(root, "bs").to_number(), 10.0);
        assert_eq!(rt.get(root, "other").to_number(), 11.0);
        rt.tick(50.0);
        assert_eq!(rt.get(root, "bs").to_number(), 55.0);
        rt.tick(100.0);
        assert_eq!(rt.get(root, "bs").to_number(), 100.0);
        rt.set(root, "w", Value::Num(20.0));
        assert_eq!(rt.get(root, "other").to_number(), 21.0);
        assert_eq!(rt.get(root, "bs").to_number(), 100.0);
        rt.set(root, "on", Value::Bool(false));
        assert_eq!(rt.get(root, "st").to_js_string(), "");
        assert_eq!(rt.get(root, "other").to_number(), 1.0);
        rt.tick(150.0);
        assert_eq!(rt.get(root, "bs").to_number(), 60.0);
        rt.tick(200.0);
        assert_eq!(rt.get(root, "bs").to_number(), 20.0);
        rt.set(root, "w", Value::Num(30.0));
        assert_eq!(rt.get(root, "bs").to_number(), 30.0, "binding restored");
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

