    #[test]
    fn repeater_model_write_creates_delegates_inside_the_write() {
        // QQuickRepeater::setModel regenerates inside the setter, also when a binding on
        // `model` updates: the delegates exist on the next line. Qt 6.12 (PySide6 6.12.0).
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property string out: ""
    property int n: 0
    property var arr: []
    Repeater {
        id: r1; model: 0
        Item { Component.onCompleted: root.out += "c" + index + ";"; Component.onDestruction: root.out += "d" + index + ";" }
    }
    Repeater {
        id: r2; model: root.n
        Item { Component.onCompleted: root.out += "b" + index + ";" }
    }
    Repeater {
        id: r3; model: root.arr
        Item { required property var modelData; Component.onCompleted: root.out += "a" + modelData + ";" }
    }
    function go() {
        out = "";
        r1.model = 2;
        out += "r1:" + r1.count + "/" + (r1.itemAt(1) !== null) + ";";
        r1.model = 1;
        out += "r1:" + r1.count + "/" + (r1.itemAt(0) !== null) + ";";
        n = 2;
        out += "r2:" + r2.count + "/" + (r2.itemAt(1) !== null) + ";";
        arr = ["x", "y"];
        out += "r3:" + r3.count + "/" + (r3.itemAt(1) !== null) + ";";
    }
}"#,
            )
            .unwrap();
        rt.settle();
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(
            rt.get(root, "out").to_js_string(),
            "c0;c1;r1:2/true;d1;d0;c0;r1:1/true;b0;b1;r2:2/true;ax;ay;r3:2/true;"
        );
    }

    #[test]
    fn delegators_written_by_a_change_handler_build_inside_the_write() {
        // A change handler runs inside the binding update that changed the property, and a
        // Repeater `model` or Loader `active` it writes still builds inside that write
        // (QQuickRepeater::setModel, QQuickLoader::setActive). Qt 6.12 (PySide6 6.12.0).
        let cases = [
            (
                r#"property var pages: ["a", "b"]
    onWChanged: {
        pages = ["c"];
        out += "reset:" + rep.count + ";";
    }
    Repeater {
        id: rep
        model: root.pages
        Loader {
            required property var modelData
            sourceComponent: Item { Component.onCompleted: root.out += "it" + modelData + ";" }
            onLoaded: root.out += "loaded" + modelData + ";"
            Component.onDestruction: root.out += "ld" + modelData + ";"
        }
    }
    function go() { out = ""; v = 1; out += "after:" + rep.count + ";" }"#,
                "ldb;lda;itc;loadedc;reset:1;after:1;",
            ),
            (
                r#"onWChanged: {
        b.active = true;
        out += "b:" + (b.item ? b.item.k : "null") + ";";
    }
    Loader {
        id: b
        active: false
        sourceComponent: Item { property int k: 7; Component.onCompleted: root.out += "bdone;" }
        onLoaded: root.out += "bloaded;"
    }
    function go() { out = ""; v = 1; out += "after;" }"#,
                "bdone;bloaded;b:7;after;",
            ),
        ];
        for (body, want) in cases {
            let mut rt = Runtime::new(None);
            let root = rt
                .load_str(&format!(
                    "import QtQuick\nItem {{\n    id: root\n    property string out: \"\"\n    property int v: 0\n    property int w: v * 2\n    {body}\n}}"
                ))
                .unwrap();
            rt.settle();
            rt.call_method(root, "go", vec![]).unwrap().unwrap();
            rt.settle();
            assert!(rt.errors().is_empty(), "{:?}", rt.errors());
            assert_eq!(rt.get(root, "out").to_js_string(), want);
        }
    }

    #[test]
    fn creation_notifies_only_from_bindings() {
        // Qt 6.12: values assigned while populating (literals, also a Loader's withheld
        // activeChanged) emit nothing; bindings run in finalize() emit when the value differs
        // from the property's default.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property bool on: false
    property string out: ""
    Loader { onActiveChanged: root.out += "litAfter;"; active: false; sourceComponent: Item {} }
    Loader { active: false; onActiveChanged: root.out += "lit;"; sourceComponent: Item {} }
    Loader { active: root.on; onActiveChanged: root.out += "bind;"; sourceComponent: Item {} }
    Loader { active: false || root.on; onActiveChanged: root.out += "bindexpr;"; sourceComponent: Item {} }
    Loader { active: true; onActiveChanged: root.out += "littrue;"; sourceComponent: Item {} }
    Loader { active: !root.on; onActiveChanged: root.out += "bindtrue;"; sourceComponent: Item {} }
    Item { visible: false; onVisibleChanged: root.out += "vislit;" }
    Item { visible: root.on; onVisibleChanged: root.out += "visbind;" }
    Item { opacity: 0.5; onOpacityChanged: root.out += "oplit;" }
    Item { opacity: root.on ? 1 : 0.5; onOpacityChanged: root.out += "opbind;" }
    Item { width: 5; onWidthChanged: root.out += "wlit;" }
    Item { width: root.on ? 1 : 5; onWidthChanged: root.out += "wbind;" }
    Timer { running: false; onRunningChanged: root.out += "tlit;" }
    Timer { interval: 5; onIntervalChanged: root.out += "tilit;" }
    Timer { interval: root.on ? 1 : 5; onIntervalChanged: root.out += "tibind;" }
    Item { property int p: 3; onPChanged: root.out += "plit;" }
    Item { property int p: root.on ? 1 : 3; onPChanged: root.out += "pbind;" }
    Text { text: "x"; onTextChanged: root.out += "textlit;" }
    Text { text: root.on ? "a" : "x"; onTextChanged: root.out += "textbind;" }
}"#,
            )
            .unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        let out = rt.get(root, "out").to_js_string();
        let mut got: Vec<&str> = out.split_terminator(';').collect();
        got.sort_unstable();
        assert_eq!(
            got,
            [
                "bind", "bindexpr", "opbind", "pbind", "textbind", "tibind", "visbind", "wbind"
            ]
        );
    }

    #[test]
    fn creation_constants_are_qmlir_constants() {
        // Qt 6.12 compiles only plain literals and enum references to non-`var` properties as
        // constants; parenthesized, negated-boolean, object/array literals are bindings.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property bool on: false
    property string out: ""
    Text { horizontalAlignment: Text.AlignRight; onHorizontalAlignmentChanged: root.out += "enumlit;" }
    Item { property int e: Text.AlignRight; onEChanged: root.out += "enumint;" }
    Item { property var e: Text.AlignRight; onEChanged: root.out += "enumvar;" }
    Item { property var m: ({a: 1}); onMChanged: root.out += "objlit;" }
    Item { property var m: [1, 2]; onMChanged: root.out += "arrlit;" }
    Item { property int m: -1; onMChanged: root.out += "neg;" }
    Item { property string m: "a"; onMChanged: root.out += "str;" }
    Item { property var m: null; onMChanged: root.out += "null;" }
    Item { property var m: undefined; onMChanged: root.out += "undef;" }
    Item { property real m: 1 + 1; onMChanged: root.out += "sum;" }
    Item { property string m: qsTr("x"); onMChanged: root.out += "qstr;" }
    Item { property color m: "red"; onMChanged: root.out += "color;" }
    Item { property int m: (5); onMChanged: root.out += "paren;" }
    Item { property bool m: !false; onMChanged: root.out += "not;" }
    Item { property int m: { return 5 }; onMChanged: root.out += "block;" }
    Loader { active: Boolean(false); onActiveChanged: root.out += "ldcall;" }
    Item { property int m: 5 // c
        onMChanged: root.out += "linecomment;" }
    Item { property string m: "a" /* x */; onMChanged: root.out += "blockcomment;" }
    Item { property bool m: true // c
        onMChanged: root.out += "boolcomment;" }
    Text { horizontalAlignment: Text.AlignRight // c
        onHorizontalAlignmentChanged: root.out += "enumcomment;" }
    Item { property string m: `a`; onMChanged: root.out += "tmpl;" }
    Text { text: `y`; onTextChanged: root.out += "texttmpl;" }
    Item { property string m: `${root.width}`; onMChanged: root.out += "tmplsub;" }
    Item { property int m: - /* c */ 5; onMChanged: root.out += "negcomment;" }
    Item { property int m: +5; onMChanged: root.out += "plus;" }
}"#,
            )
            .unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        let out = rt.get(root, "out").to_js_string();
        let mut got: Vec<&str> = out.split_terminator(';').collect();
        got.sort_unstable();
        assert_eq!(
            got,
            [
                "arrlit", "block", "enumvar", "ldcall", "not", "objlit", "paren", "plus", "qstr",
                "sum", "tmplsub"
            ]
        );
    }

