    #[test]
    fn script_model_values_keep_binding_made_objects() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nimport Quickshell\nItem { id: root; property int n: 0\n Component { id: comp; QtObject { property int v } }\n property var made: [comp.createObject(null, {v: n}), comp.createObject(null, {v: -n})]\n property var shown: []\n Component.onCompleted: shown = [made[0]]\n ScriptModel { id: sm; values: root.n < 3 ? root.shown : [] }\n Timer { interval: 10; running: true; repeat: true; onTriggered: n++ } }\n",
            )
            .unwrap();
        rt.settle();
        let first = match rt.get(root, "shown") {
            Value::Obj(o) => o.borrow().array.as_ref().unwrap()[0].clone(),
            v => panic!("{v:?}"),
        };
        let Value::Item(first) = first else { panic!() };
        let mut t = 1;
        while rt.get(root, "n").to_number() < 2.0 {
            rt.tick(t as f64 * 16.0);
            t += 1;
        }
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        {
            let w = rt.world.borrow();
            // The model's rows outlive the generation that made them; the rest is freed.
            assert!(!w.dead.contains(&first));
            assert!(w.sm_holds.keys().all(|x| !w.dead.contains(x)));
            assert_eq!(w.sm_values.len(), 1);
        }
        while rt.get(root, "n").to_number() < 6.0 {
            rt.tick(t as f64 * 16.0);
            t += 1;
        }
        // Dropped from the model, `first` is retired with its generation.
        rt.world.borrow_mut().purge_dead();
        let w = rt.world.borrow();
        assert!(w.dead.contains(&first));
        assert!(w.sm_values.is_empty() && w.sm_holds.is_empty());
    }

    #[test]
    fn arena_ids_skip_released_chunks() {
        let mut a = Arena::default();
        for _ in 0..4 * CHUNK {
            a.push(Inst::default());
        }
        let keep = 3 * CHUNK + 5;
        for i in (0..4 * CHUNK).filter(|&i| i != keep) {
            a.release(i);
        }
        assert_eq!(a.take_freed(), vec![0, 1, 2]);
        assert_eq!(a.ids().collect::<Vec<_>>(), vec![keep]);
        assert_eq!(a.len(), 4 * CHUNK);
    }

    #[test]
    fn chunks_left_with_a_few_slots_are_given_up_for_lists() {
        let mut c = Chunked::<usize>::default();
        for i in 0..3 * CHUNK + 7 {
            c.push(i);
        }
        let kept = [5, CHUNK - 1, CHUNK + 300, 3 * CHUNK + 2];
        for i in (0..3 * CHUNK + 7).filter(|i| !kept.contains(i)) {
            assert_eq!(c.release(i), i == 3 * CHUNK - 1, "{i}");
        }
        // The last chunk is still being filled; the one freed whole is already gone.
        assert_eq!(c.capacity(), 3 * CHUNK);
        assert_eq!(c.compact(), vec![0, 1]);
        assert!(c.capacity() < CHUNK + 16, "{}", c.capacity());
        assert_eq!(c.compact(), Vec::<usize>::new());
        assert_eq!(c.ids().collect::<Vec<_>>(), kept);
        for i in 0..c.len() {
            assert_eq!(c.get(i), kept.contains(&i).then_some(&i), "{i}");
        }
        let all: Vec<_> = c.iter().collect();
        assert_eq!(all.len(), c.len());
        assert!(all.iter().enumerate().all(|(i, v)| *v == c.get(i)));
        // A released slot of a listed chunk refills in the list; the chunk's last one frees it.
        assert_eq!(*c.get_or_insert_with(7, || 70), 70);
        assert_eq!(*c.get_or_insert_with(5, || 50), 5);
        assert_eq!(c.ids_in(0).collect::<Vec<_>>(), [5, 7, CHUNK - 1]);
        assert!(!c.release(5) && !c.release(5) && !c.release(7));
        assert!(c.release(CHUNK - 1));
        assert_eq!(c.get(CHUNK - 1), None);
        assert_eq!(c.ids().collect::<Vec<_>>(), kept[2..]);

        let mut v = ChunkVec::<u32>::new();
        for i in 0..CHUNK {
            *v.get_mut(CHUNK + i) = i as u32 + 1;
        }
        v.keep_only(1, [CHUNK + 300, CHUNK + 301].into_iter());
        assert_eq!(v.allocated(), (0, 2));
        assert_eq!(
            [299, 300, 301, 302].map(|k| v.get(CHUNK + k)),
            [0, 301, 302, 0]
        );
        *v.get_mut(CHUNK + 300) = 9;
        *v.get_mut(CHUNK + 2) = 3;
        assert_eq!(v.allocated(), (0, 3));
        assert_eq!([2, 300].map(|k| v.get(CHUNK + k)), [3, 9]);
        v.keep_only(1, std::iter::empty());
        assert_eq!(v.allocated(), (0, 0));
        assert_eq!(v.get(CHUNK + 300), 0);
    }

    /// The original keeps each notification's object for the history while the popup built around it
    /// (about a thousand instances and contexts) is destroyed: every such object held the
    /// chunk of ids it was created in, ~31 KiB a notification for as long as the shell ran.
    #[test]
    fn objects_outliving_their_neighbours_do_not_hold_their_chunks() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property bool on: false
    property var kept: []
    Component { id: note; QtObject { property int n: -1 } }
    Loader {
        active: root.on
        sourceComponent: Column { Repeater { model: 600; delegate: Item { Item {} } } }
    }
    function keep(n) { kept.push(note.createObject(root, { n: n })) }
    function sum() { let s = 0; for (const k of kept) s += k.n; return s }
}"#,
            )
            .unwrap();
        rt.settle();
        let rounds = 40;
        for n in 0..rounds {
            rt.set(root, "on", Value::Bool(true));
            rt.settle();
            rt.call_method(root, "keep", vec![Value::Num(n as f64)])
                .unwrap()
                .unwrap();
            rt.set(root, "on", Value::Bool(false));
            rt.settle();
            // The host's maintenance: the batched sweep, then the throttled purge.
            let mut w = rt.world.borrow_mut();
            let ids = std::mem::take(&mut w.reaped);
            w.sweep_dead(&ids);
            w.purge_dead();
        }
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        {
            let w = rt.world.borrow();
            assert!(w.items.len() > rounds * CHUNK, "{}", w.items.len());
            assert!(w.ctxs.len() > rounds * CHUNK / 2, "{}", w.ctxs.len());
            assert!(w.items.capacity() < 4 * CHUNK, "{}", w.items.capacity());
            assert!(w.ctxs.capacity() < 4 * CHUNK, "{}", w.ctxs.capacity());
        }
        let sum = rt.call_method(root, "sum", vec![]).unwrap().unwrap();
        assert_eq!(sum.to_number(), (rounds * (rounds - 1) / 2) as f64);
    }

    /// A root with one instance destroyed and its slot released: (runtime, root, released id).
    fn with_a_released_item() -> (Runtime, usize, usize) {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    property bool on: true
    property alias it: l.item
    Loader { id: l; active: parent.on; sourceComponent: Item {} }
}"#,
            )
            .unwrap();
        rt.settle();
        let Value::Item(gone) = rt.get(root, "it") else {
            panic!("no loaded item");
        };
        rt.set(root, "on", Value::Bool(false));
        rt.settle();
        {
            let mut w = rt.world.borrow_mut();
            let ids = std::mem::take(&mut w.reaped);
            w.sweep_dead(&ids);
            assert!(!w.items.holds(gone));
        }
        (rt, root, gone)
    }

    /// docs/qt-differences.md, "A Repeater's model written while the Repeater builds": Qt 6.12
    /// rebuilds inside the write (`abBcCA 2` and `abBA 1`), here the build in progress returns
    /// first. The delegate let go stays readable to the handler that wrote, as in Qt.
    #[test]
    fn a_repeater_whose_model_is_written_during_its_build_rebuilds_after_it() {
        let run = |delegate: &str| {
            let mut rt = Runtime::new(None);
            let src = format!(
                r#"import QtQuick
Item {{
    id: root
    property var m: ["a"]
    property string log: ""
    property string result: log + " " + rep.count
    Repeater {{
        id: rep
        model: root.m
        delegate: Item {{
            id: d
            required property string modelData
            {delegate}
        }}
    }}
}}
"#
            );
            let root = rt.load_str(&src).unwrap();
            rt.settle();
            assert_eq!(rt.world.borrow().errors, Vec::<String>::new());
            rt.get(root, "result").to_js_string()
        };
        let by_the_delegate = r#"Component.onCompleted: {
                root.log += d.modelData
                if (root.m.length == 1)
                    root.m = ["b", "c"]
                root.log += d.modelData.toUpperCase()
            }"#;
        assert_eq!(run(by_the_delegate), "aAbBcC 2");
        let by_its_layer_effect = r#"layer.enabled: true
            layer.effect: Item {
                Component.onCompleted: {
                    root.log += d.modelData
                    if (root.m[0] == "a")
                        root.m = ["b"]
                    root.log += d.modelData.toUpperCase()
                }
            }"#;
        assert_eq!(run(by_its_layer_effect), "aAbB 1");
    }

    /// `Runtime::set` with the id of a destroyed object (aotcheck does it) is no mistake.
    #[test]
    fn the_host_sets_nothing_on_a_released_item() {
        let (mut rt, _, gone) = with_a_released_item();
        rt.set(gone, "width", Value::Num(7.0));
        assert!(!rt.world.borrow().items.holds(gone));
    }

    /// `items[id]` for writing with a released id is a mistake in the code that does it (the
    /// instance is gone; `get_mut` is the way to ask): the test that runs into it fails.
    #[test]
    #[should_panic(expected = "a write to the released item")]
    fn index_mut_of_a_released_slot_fails_the_test_that_does_it() {
        let (rt, root, gone) = with_a_released_item();
        rt.world.borrow_mut().items[gone].parent = Some(root);
    }

    /// The failure names the property whose write reached the released slot.
    #[test]
    #[should_panic(expected = "(in the write of `width`)")]
    fn index_mut_of_a_released_slot_names_the_property_being_written() {
        let (rt, root, gone) = with_a_released_item();
        let mut w = rt.world.borrow_mut();
        // What `World::write(root, "width", ..)` holds while its setters run.
        w.items.writing = Some(Sym::new("width"));
        w.items[gone].parent = Some(root);
    }

    /// The shell (`debug::log_code_errors`) says the mistake once for each place that makes it
    /// and goes on: the write creates nothing. A build with debug assertions panics there too.
    #[test]
    #[cfg(not(debug_assertions))]
    fn the_shell_logs_index_mut_of_a_released_slot_once_for_each_place() {
        const TEST: &str = concat!(
            module_path!(),
            "::the_shell_logs_index_mut_of_a_released_slot_once_for_each_place"
        );
        if testenv::in_own_process(TEST) {
            crate::debug::log_code_errors();
            let (rt, root, gone) = with_a_released_item();
            let mut w = rt.world.borrow_mut();
            for _ in 0..3 {
                w.items[gone].parent = Some(root);
            }
            w.items.writing = Some(Sym::new("width"));
            w.items[gone].parent = Some(root);
            assert!(w.items[gone].parent.is_none() && !w.items.holds(gone));
            return;
        }
        let out = testenv::own_process_command(TEST).output().unwrap();
        assert!(out.status.success(), "{out:?}");
        let log = String::from_utf8_lossy(&out.stderr);
        let said: Vec<&str> = log
            .lines()
            .filter(|l| l.starts_with("impulse-shell: internal error"))
            .collect();
        assert_eq!(said.len(), 2, "{log}");
        assert!(
            said[0].contains(concat!(" at ", file!(), ":"))
                && said[0].contains(": a write to the released item ")
                && said[0].ends_with(" (outside a property write)"),
            "{log}"
        );
        assert!(said[1].ends_with("(in the write of `width`)"), "{log}");
    }

    /// A write to a destroyed instance creates nothing: its released slot stays released. An
    /// animation that outlives its target writes nothing more and runs on to its end, as in
    /// Qt 6.12 (measured with qmltestrunner: started, the target destroyed, then stopped and
    /// finished at the animation's own time; a sequence goes on to its next steps).
    #[test]
    fn writes_after_destruction_create_nothing() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property bool on: true
    property string log: ""
    Loader { id: l; active: root.on; sourceComponent: Item { property real v: 0 } }
    NumberAnimation {
        id: anim; property: "v"; from: 0; to: 100; duration: 400
        onFinished: root.log += "finished;"
    }
    SequentialAnimation {
        id: seq
        property var o
        NumberAnimation { target: seq.o; property: "v"; from: 0; to: 50; duration: 200 }
        ScriptAction { script: root.log += "script;" }
        PropertyAction { target: seq.o; property: "v"; value: 7 }
        onFinished: root.log += "seq finished;"
    }
    function go() { anim.target = l.item; seq.o = l.item; anim.start(); seq.start() }
    function busy() { return anim.running || seq.running }
    function target() { return l.item }
}"#,
            )
            .unwrap();
        rt.settle();
        let gone = match rt.call_method(root, "target", vec![]).unwrap().unwrap() {
            Value::Item(i) => i,
            v => panic!("{v:?}"),
        };
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.tick(100.0);
        assert_eq!(rt.get(gone, "v").to_number(), 25.0);
        rt.set(root, "on", Value::Bool(false));
        rt.settle();
        {
            let mut w = rt.world.borrow_mut();
            assert!(w.dead.contains(&gone));
            let ids = std::mem::take(&mut w.reaped);
            w.sweep_dead(&ids);
            assert!(!w.items.holds(gone));
            // By the engine's own entry points too.
            assert!(!w.write(gone, "v", Value::Num(7.0)));
            assert!(w.items.get_mut(gone).is_none());
        }
        rt.tick(150.0);
        assert!(
            rt.call_method(root, "busy", vec![])
                .unwrap()
                .unwrap()
                .truthy()
        );
        assert!(
            !rt.world.borrow().items.holds(gone),
            "a running animation's write"
        );
        rt.tick(250.0);
        rt.settle();
        assert_eq!(rt.get(root, "log").to_js_string(), "script;seq finished;");
        rt.tick(450.0);
        rt.settle();
        assert!(
            !rt.call_method(root, "busy", vec![])
                .unwrap()
                .unwrap()
                .truthy()
        );
        assert_eq!(
            rt.get(root, "log").to_js_string(),
            "script;seq finished;finished;"
        );
        assert!(
            !rt.world.borrow().items.holds(gone),
            "the animations' last writes"
        );
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    /// The same for a SmoothedAnimation, which writes on every tick until it arrives.
    #[test]
    fn a_smoothed_animation_creates_nothing_for_a_destroyed_target() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property bool on: true
    Loader { id: l; active: root.on; sourceComponent: Item { property real v: 0 } }
    SmoothedAnimation { id: anim; property: "v"; to: 100; velocity: 100 }
    function go() { anim.target = l.item; anim.start() }
    function target() { return l.item }
}"#,
            )
            .unwrap();
        rt.settle();
        let gone = match rt.call_method(root, "target", vec![]).unwrap().unwrap() {
            Value::Item(i) => i,
            v => panic!("{v:?}"),
        };
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.tick(100.0);
        let v = rt.get(gone, "v").to_number();
        assert!(v > 0.0 && v < 100.0, "{v}");
        rt.set(root, "on", Value::Bool(false));
        rt.settle();
        {
            let mut w = rt.world.borrow_mut();
            assert!(w.dead.contains(&gone));
            let ids = std::mem::take(&mut w.reaped);
            w.sweep_dead(&ids);
            assert!(!w.items.holds(gone));
        }
        for t in [200.0, 600.0, 1500.0] {
            rt.tick(t);
            rt.settle();
            assert!(!rt.world.borrow().items.holds(gone), "at {t} ms");
        }
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn missing_prop_lookups_do_not_intern() {
        let mut p = Props::default();
        let k = "\x01audit-unseen-key-7f3a";
        assert!(p.get(k).is_none());
        assert!(!p.contains_key(k));
        assert!(p.get_mut(k).is_none());
        assert!(p.remove(k).is_none());
        assert!(Sym::lookup(k).is_none());
        p.insert(k, Prop::default());
        assert!(p.contains_key(k));
        assert_eq!(Sym::lookup(k), Some(Sym::new(k)));
        assert!(p.remove(k).is_some());
    }

    #[test]
    fn sync_flush_reports_binding_loops_like_settle() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property bool on: false\n property int p: on ? q + 1 : 0\n property int q: p + 1\n property int pn: 0\n onPChanged: pn++\n function go() { on = true; return p }\n}\n",
            )
            .unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        let pn = rt.get(root, "pn").to_number();
        // A JS write updates dependents synchronously: p's update runs q's, which re-enters p.
        // Like QQmlBinding's updatingFlag the re-entry is reported and skipped, so p keeps
        // the value of its own update and changes once.
        let r = rt.call_method(root, "go", vec![]).unwrap().unwrap();
        assert_eq!(r.to_number(), 2.0);
        assert_eq!(rt.get(root, "q").to_number(), 3.0);
        assert_eq!(rt.get(root, "pn").to_number(), pn + 1.0);
        let errs = rt.errors();
        assert!(
            errs.iter()
                .any(|e| e.starts_with("binding loop detected") && e.contains("property p")),
            "{errs:?}"
        );
    }

    #[test]
    fn handler_write_reentering_its_binding_is_a_loop() {
        // QQmlBinding::update: w's write emits wChanged inside w's update, so the handler's
        // write to h re-enters w. Qt reports the loop and keeps w's value; nothing repeats.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property int h: 1\n property int w: h * 2\n property int hits: 0\n onWChanged: { hits++; h++ }\n function go() { h = 5 }\n}\n",
            )
            .unwrap();
        rt.settle();
        let _ = rt.errors();
        let hits = rt.get(root, "hits").to_number();
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.settle();
        assert_eq!(rt.get(root, "w").to_number(), 10.0);
        assert_eq!(rt.get(root, "h").to_number(), 6.0);
        assert_eq!(rt.get(root, "hits").to_number(), hits + 1.0);
        let errs = rt.errors();
        assert!(
            errs.iter()
                .any(|e| e.starts_with("binding loop detected") && e.contains("property w")),
            "{errs:?}"
        );
    }

    #[test]
    fn binding_with_several_changed_inputs_updates_once() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property var c: ({n: 0})\n property int a\n property int b\n property int d\n property int s: { c.n++; return a + b + d }\n}\n",
            )
            .unwrap();
        rt.settle();
        let n = |rt: &mut Runtime| match rt.get(root, "c") {
            Value::Obj(o) => o.borrow().props.get("n").map_or(-1.0, |v| v.to_number()),
            _ => -1.0,
        };
        let before = n(&mut rt);
        {
            let mut w = rt.world.borrow_mut();
            for (k, v) in [("a", 1.0), ("b", 2.0), ("d", 3.0)] {
                w.write(root, k, Value::Num(v));
            }
            // One queue entry per binding, however many of its inputs changed.
            assert_eq!(w.dirty.keys().count(), 1);
        }
        rt.settle();
        assert_eq!(rt.get(root, "s").to_number(), 6.0);
        assert_eq!(n(&mut rt) - before, 1.0);
    }

    #[test]
    fn destroyed_bindings_leave_their_sources() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str("import QtQuick\nItem {\n property int q\n Item { id: kid; property int r: parent.q + 1 }\n}\n")
            .unwrap();
        rt.settle();
        let kid = rt.id("kid").unwrap();
        let readers = |rt: &Runtime| {
            rt.world
                .borrow()
                .dependents
                .get(&(root, Sym::new("q")))
                .map_or(0, |s| s.iter().filter(|d| d.0 == kid).count())
        };
        assert_eq!(readers(&rt), 1);
        rt.world.borrow_mut().destroy(kid);
        // QQmlNotifierEndpoint::disconnect: no dead endpoint is left for notifications to skip.
        assert_eq!(readers(&rt), 0);
        rt.set(root, "q", Value::Num(2.0));
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn read_lists_reconnect_in_place() {
        // Short (positional scan) and long (deduplicated through a set) read lists alike: inputs
        // no longer read are disconnected, the rest stay connected once.
        for n in [3usize, 40] {
            let props: String = (0..n)
                .map(|i| format!(" property int p{i}: {i}\n"))
                .collect();
            let all: Vec<String> = (0..n).map(|i| format!("p{i}")).collect();
            let half = &all[..n / 2];
            let src = format!(
                "import QtQuick\nItem {{\n property bool sw: true\n{props} property int s: sw ? {} + {} : {}\n}}\n",
                all.join(" + "),
                all.join(" + "),
                half.join(" + ")
            );
            let mut rt = Runtime::new(None);
            let root = rt.load_str(&src).unwrap();
            rt.settle();
            let links = |rt: &Runtime, i: usize| {
                rt.world
                    .borrow()
                    .dependents
                    .get(&(root, Sym::new(&format!("p{i}"))))
                    .map_or(0, |s| s.iter().filter(|d| d.1 == "s").count())
            };
            let sum = |k: usize| (0..k).sum::<usize>() as f64;
            assert_eq!(rt.get(root, "s").to_number(), 2.0 * sum(n));
            assert!((0..n).all(|i| links(&rt, i) == 1));
            rt.set(root, "sw", Value::Bool(false));
            rt.settle();
            assert_eq!(rt.get(root, "s").to_number(), sum(n / 2));
            assert!((0..n / 2).all(|i| links(&rt, i) == 1), "n {n}");
            assert!((n / 2..n).all(|i| links(&rt, i) == 0), "n {n}");
            rt.set(root, "p0", Value::Num(100.0));
            rt.settle();
            assert_eq!(rt.get(root, "s").to_number(), sum(n / 2) + 100.0);
            rt.set(root, "sw", Value::Bool(true));
            rt.settle();
            assert!((0..n).all(|i| links(&rt, i) == 1), "n {n}");
            assert_eq!(rt.get(root, "s").to_number(), 2.0 * (sum(n) + 100.0));
        }
    }

    #[test]
    fn nested_sync_updates_reuse_interpreters() {
        let mut src = String::from("Item { function go() { p0++ }\n");
        for i in 0..8 {
            src += &format!("property int p{i}\nonP{i}Changed: p{} = p{i}\n", i + 1);
        }
        src += "property int p8\n}";
        let mut rt = Runtime::new(None);
        let r = rt.load_str(&src).unwrap();
        rt.settle();
        let pool = |rt: &Runtime| {
            let mut v: Vec<usize> = rt
                .world
                .borrow()
                .spare
                .iter()
                .map(|i| &**i as *const Interp as usize)
                .collect();
            v.sort_unstable();
            v
        };
        rt.call_method(r, "go", vec![]).unwrap().unwrap();
        assert_eq!(rt.get(r, "p8").to_number(), 1.0);
        let first = pool(&rt);
        assert!(
            first.len() >= 8,
            "one interpreter per nesting level: {}",
            first.len()
        );
        rt.call_method(r, "go", vec![]).unwrap().unwrap();
        assert_eq!(rt.get(r, "p8").to_number(), 2.0);
        // The same interpreters run the chain again: none is built or dropped.
        assert_eq!(pool(&rt), first);
    }

    /// A parked interpreter has no World to work on. Work that reaches one took it past
    /// `World::take_interp`: a mistake in the code, which fails the test that runs into it.
    #[test]
    #[should_panic(expected = "an interpreter parked in World::spare was used (Host::lookup)")]
    fn a_parked_interpreter_fails_the_test_that_uses_it() {
        let _ = Parked.lookup(None, "name");
    }

    /// The shell (`debug::log_code_errors`) says the same mistake once and goes on: the parked
    /// interpreter answers as a host with nothing in it.
    #[test]
    fn the_shell_logs_the_use_of_a_parked_interpreter_once() {
        const TEST: &str = concat!(
            module_path!(),
            "::the_shell_logs_the_use_of_a_parked_interpreter_once"
        );
        if testenv::in_own_process(TEST) {
            crate::debug::log_code_errors();
            assert!(Parked.lookup(None, "name").is_none());
            assert!(Parked.get(0, "name").is_none());
            assert!(!Parked.set(0, "name", Value::Null));
            return;
        }
        let out = testenv::own_process_command(TEST).output().unwrap();
        assert!(out.status.success(), "{out:?}");
        let log = String::from_utf8_lossy(&out.stderr);
        let said: Vec<&str> = log
            .lines()
            .filter(|l| l.starts_with("impulse-shell: internal error"))
            .collect();
        assert_eq!(said.len(), 1, "{log}");
        assert!(
            said[0].ends_with(
                "an interpreter parked in World::spare was used (Host::lookup); \
                 only World::take_interp hands one out"
            ),
            "{log}"
        );
    }

    /// The World ends with its Runtime: an interpreter parked in `spare` after a synchronous
    /// update does not hold it, so what the World owns (the stop flag of its jobs and
    /// services, its watches and channels) is dropped with the last object that uses it.
    #[test]
    fn world_is_dropped_with_its_runtime() {
        let mut rt = Runtime::new(None);
        let r = rt
            .load_str(
                "Item { property int p\nproperty int q\nonPChanged: q = p\nfunction go() { p++ } }",
            )
            .unwrap();
        rt.settle();
        rt.call_method(r, "go", vec![]).unwrap().unwrap();
        assert_eq!(rt.get(r, "q").to_number(), 1.0);
        assert!(
            !rt.world.borrow().spare.is_empty(),
            "the handler ran in a spare interpreter, parked again"
        );
        let stop = rt.world.borrow().jobs_stop.0.clone();
        let world = Rc::downgrade(&rt.world);
        drop(rt);
        assert!(world.upgrade().is_none(), "the World outlived its Runtime");
        assert!(stop.load(std::sync::atomic::Ordering::Acquire));
    }

    #[test]
    fn timer_interval_write_is_no_read_of_the_writer() {
        // A binding that retimes its Timer reads nothing by writing:
        // the old interval QQmlTimer compares against is the timer's own state.
        let mut rt = Runtime::new(None);
        rt.load_str(
            "import QtQuick\nItem { property bool on: true\n Timer { id: t; interval: 200; repeat: true; running: { t.interval = 50; return parent.on } } }\n",
        )
        .unwrap();
        rt.settle();
        let t = rt.id("t").unwrap();
        let w = rt.world.borrow();
        let deps = &w.items[t].props.get("running").unwrap().deps;
        assert!(
            !deps.iter().any(|d| d.0 == t && d.1 == "interval"),
            "{deps:?}"
        );
        assert!(
            w.errors.iter().all(|e| !e.contains("binding loop")),
            "{:?}",
            w.errors
        );
    }

    #[test]
    fn storing_an_unset_property_default_notifies_nothing() {
        // StyledSpinBox: `text: root.value; onTextChanged: root.value = parseFloat(text)`. The
        // SpinBox's value was 0 all along, so writing 0 is no change: no valueChanged, and the
        // text binding is not re-entered from its own change handler.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nimport QtQuick.Controls\nItem { property int hits\n SpinBox { id: sb; onValueChanged: hits++ }\n TextInput { text: sb.value; onTextChanged: sb.value = parseFloat(text) } }\n",
            )
            .unwrap();
        rt.settle();
        assert_eq!(rt.get(root, "hits").to_number(), 0.0);
        assert!(
            rt.errors().iter().all(|e| !e.contains("binding loop")),
            "{:?}",
            rt.errors()
        );
    }

    #[test]
    fn self_requeueing_signal_is_dropped_with_named_handler() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem {\n property int n: 0\n property int m: 0\n signal s()\n onS: { n++; s() }\n Component.onCompleted: s()\n}\n",
            )
            .unwrap();
        let cpu = crate::watchdog::thread_cpu_time;
        let t = cpu();
        rt.settle();
        assert!(
            cpu() - t < std::time::Duration::from_secs(1),
            "{:?}",
            cpu() - t
        );
        // `s()` runs its handlers inside the call, so the recursion ends where V4's does: the
        // innermost call throws RangeError, which ends that handler.
        let errs = rt.errors();
        assert!(
            errs.iter()
                .any(|e| e.ends_with("Maximum call stack size exceeded")),
            "{errs:?}"
        );
        let n = rt.get(root, "n").to_number();
        assert!(n > 0.0);
        // Nothing of the loop is left queued for a later settle to deliver.
        rt.set(root, "m", Value::Num(1.0));
        rt.settle();
        assert_eq!(rt.get(root, "n").to_number(), n);
    }

    #[test]
    fn markdown_to_plain_converts_in_the_setter() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nTextEdit {\n textFormat: TextEdit.MarkdownText\n text: \"a\\nb\"\n property string seen\n onTextFormatChanged: seen = text\n}\n",
            )
            .unwrap();
        rt.settle();
        let bold = crate::colorscheme::system_font().weight > 400;
        let src = crate::markdown::round_trip_in("a\nb", bold);
        assert_ne!(src, "a\nb");
        // QFontInfo(QFont()).bold() under kdeglobals' Medium: every block is written bold.
        assert_eq!(crate::markdown::round_trip("tool"), "tool\n\n");
        assert_eq!(crate::markdown::round_trip_in("tool", true), "**tool**\n\n");
        rt.world
            .borrow_mut()
            .write(root, "textFormat", Value::Num(0.0));
        // Before any settle, like QQuickTextEdit::setTextFormat.
        assert_eq!(rt.get(root, "text").to_js_string(), src);
        rt.settle();
        assert_eq!(rt.get(root, "text").to_js_string(), src);
    }

