    #[test]
    fn replayed_delegates_apply_grouped_anchor_changes() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property bool wide: true
    Column {
        Repeater {
            model: 3
            delegate: Item {
                width: 100; height: 30
                Item { id: icon; width: 20; height: 20 }
                Text {
                    id: label
                    objectName: "label"
                    text: "x"
                    anchors { top: icon.bottom; horizontalCenter: icon.horizontalCenter }
                    states: State {
                        name: "wide"
                        when: root.wide
                        AnchorChanges {
                            target: label
                            anchors { top: undefined; horizontalCenter: undefined; left: icon.right; verticalCenter: icon.verticalCenter }
                        }
                    }
                }
            }
        }
    }
}"#,
            )
            .unwrap();
        rt.settle();
        let labels: Vec<usize> = rt.world.borrow_mut().of_type("Text");
        assert_eq!(labels.len(), 3);
        let lines = |rt: &mut Runtime, t: usize| {
            let mut w = rt.world.borrow_mut();
            [
                "anchors.top",
                "anchors.left",
                "anchors.horizontalCenter",
                "anchors.verticalCenter",
            ]
            .map(|k| {
                !matches!(
                    w.read(t, k),
                    None | Some(Value::Undefined) | Some(Value::Null)
                )
            })
        };
        for &t in &labels {
            assert_eq!(
                rt.get(t, "state").to_js_string(),
                "wide",
                "label {t} of {labels:?}"
            );
            assert_eq!(lines(&mut rt, t), [false, true, false, true], "label {t}");
        }
        rt.set(root, "wide", Value::Bool(false));
        rt.settle();
        for &t in &labels {
            assert_eq!(lines(&mut rt, t), [true, false, true, false], "label {t}");
        }
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

