    /// The files `Qt.resolvedUrl` is asked from in the tests below: a document, a component
    /// and two JS files (one a library) in a directory under it.
    fn resolved_url_tree(name: &str) -> PathBuf {
        let d = std::env::temp_dir().join(format!("qml-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(d.join("sub")).unwrap();
        let lib = "function r(u) { return Qt.resolvedUrl(u) }\n";
        std::fs::write(d.join("sub/lib.js"), lib).unwrap();
        std::fs::write(d.join("sub/plib.js"), format!(".pragma library\n{lib}")).unwrap();
        std::fs::write(
            d.join("sub/Thing.qml"),
            r#"import QtQuick
import "lib.js" as Lib
QtObject {
    property string own: Qt.resolvedUrl("pic.png")
    property string given
    property string viaLib: Lib.r("pic.png")
    function f(u) { return Qt.resolvedUrl(u) }
}
"#,
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            r#"import QtQuick
import "sub"
import "sub/lib.js" as Lib
import "sub/plib.js" as PLib
Item {
    property string s
    Thing { id: t; given: Qt.resolvedUrl("big.png") }
    Component.onCompleted: s = [
        Qt.resolvedUrl("big.png"), Qt.resolvedUrl("sub/pic.png"), Qt.resolvedUrl("./a/../big.png"),
        t.own, t.given, t.f("pic.png"), t.viaLib, Lib.r("pic.png"), PLib.r("pic.png"),
        "[" + Qt.resolvedUrl("") + "]", Qt.resolvedUrl("http://e/x.png"),
        Qt.resolvedUrl("/abs/x.png"), Qt.resolvedUrl("a b.png"), Qt.resolvedUrl("file:///b"),
        Qt.resolvedUrl("/abs/a#b.png"), Qt.resolvedUrl("a.png#b"),
        Qt.resolvedUrl("/abs/a%20b.png"), Qt.resolvedUrl("/abs/50% a.png"),
        Qt.resolvedUrl("a%20b.png?x%20y")
    ].join("\n")
}
"#,
        )
        .unwrap();
        d
    }

    /// QtObject::resolvedUrl resolves in `callingQmlContext()`: a relative url is beside the
    /// file the calling code is written in, whichever object it is called for. The values are
    /// those of Qt 6.12 under Quickshell 0.3.2 with the same files.
    #[test]
    fn resolved_url_is_relative_to_the_file_of_the_calling_code() {
        let d = resolved_url_tree("resolved-url");
        let mut rt = Runtime::new(Some(d.clone()));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        let at = |f: &str| format!("file://{}/{f}", d.display());
        assert_eq!(
            rt.get(root, "s")
                .to_js_string()
                .split('\n')
                .collect::<Vec<_>>(),
            [
                at("big.png"),
                at("sub/pic.png"),
                at("big.png"),
                at("sub/pic.png"),
                at("big.png"),
                at("sub/pic.png"),
                at("sub/pic.png"),
                at("sub/pic.png"),
                at("sub/pic.png"),
                "[]".to_string(),
                "http://e/x.png".to_string(),
                "file:///abs/x.png".to_string(),
                at("a b.png"),
                "file:///b".to_string(),
                "file:///abs/a#b.png".to_string(),
                at("a.png#b"),
                "file:///abs/a b.png".to_string(),
                "file:///abs/50%25 a.png".to_string(),
                at("a b.png?x y"),
            ]
        );
        let _ = std::fs::remove_dir_all(&d);
    }

    /// Compiled code has no scope chain: its QML scope is the one its `Env` was made with, and
    /// the calling context is that of the innermost running body.
    #[test]
    fn resolved_url_in_compiled_code_is_relative_to_its_own_file() {
        use crate::jsrt::{Cx, Env, FnKind, FnMeta};
        static META: FnMeta = FnMeta {
            name: "f",
            kind: FnKind::Normal,
            nparams: 1,
            nslots: 0,
            strict: false,
        };
        // `Qt.resolvedUrl("pic.png")`, or with an argument `[that, arg()]`.
        fn body(cx: &mut Cx, _: &Env, _: &Value, args: &[Value]) -> crate::eval::R<Value> {
            let global = cx.global.clone();
            let qt = cx.lookup(&global, "Qt")?;
            let resolve = cx.get(&qt, "resolvedUrl")?;
            let own = cx.call(&resolve, qt, &[Value::str("pic.png")])?;
            match args.first() {
                Some(f) => {
                    let inner = cx.call(f, Value::Undefined, &[])?;
                    let after = cx.call(&resolve, Value::Undefined, &[Value::str("pic.png")])?;
                    Ok(Value::str(&format!(
                        "{} {} {}",
                        own.to_js_string(),
                        inner.to_js_string(),
                        after.to_js_string()
                    )))
                }
                None => Ok(own),
            }
        }
        let d = resolved_url_tree("resolved-url-aot");
        let mut rt = Runtime::new(Some(d.clone()));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        // The Thing is written in main.qml; its bindings are written in its own document.
        let (main, sub) = {
            let w = rt.world.borrow();
            let ctx = w.items[root].ctx.unwrap() as usize;
            let thing = w.find_id(ctx, "t").unwrap();
            let own = w.items[thing]
                .props
                .get("own")
                .unwrap()
                .binding
                .as_ref()
                .unwrap()
                .ctx;
            ((root, ctx), (thing, own))
        };
        let outer = crate::jsrt::closure(body, &Env::new(Some(main), None), &META);
        let inner = crate::jsrt::closure(body, &Env::new(Some(sub), None), &META);
        let got = rt.it.call(&outer, Value::Undefined, &[inner]).unwrap();
        let at = |f: &str| format!("file://{}/{f}", d.display());
        assert_eq!(
            got.to_js_string(),
            format!("{} {} {}", at("pic.png"), at("sub/pic.png"), at("pic.png"))
        );
        let _ = std::fs::remove_dir_all(&d);
    }

