    #[test]
    fn script_model_view_keeps_delegates_and_runs_remove_transition() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
ListView {
    id: root
    width: 100; height: 300
    property var names: ["a", "b", "c"]
    model: ScriptModel { values: root.names }
    remove: Transition { NumberAnimation { property: "opacity"; to: 0; duration: 100 } }
    add: Transition { NumberAnimation { property: "opacity"; from: 0; to: 1; duration: 100 } }
    delegate: Item { required property var modelData; required property int index; width: 100; height: 20 }
}"#,
            )
            .unwrap();
        rt.settle();
        let dels = |rt: &Runtime| rt.world.borrow().delegated[&root].1.clone();
        let before = dels(&rt);
        assert_eq!(before.len(), 3);
        rt.set(
            root,
            "names",
            Value::array(vec![Value::str("a"), Value::str("c"), Value::str("d")]),
        );
        rt.settle();
        let after = dels(&rt);
        assert_eq!((after[0], after[1]), (before[0], before[2]));
        assert_eq!(rt.get(after[1], "index").to_number(), 1.0);
        assert!(!rt.world.borrow().dead.contains(&before[1]));
        assert_eq!(rt.get(after[2], "opacity").to_number(), 0.0);
        rt.tick(50.0);
        assert_eq!(rt.get(before[1], "opacity").to_number(), 0.5);
        rt.tick(150.0);
        assert!(rt.world.borrow().dead.contains(&before[1]));
        assert_eq!(rt.get(after[2], "opacity").to_number(), 1.0);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

