    /// QQuickItemView::forceLayout lays the view out inside the call, in a window that is not
    /// shown too: the rows of a model changed there are made by it, and showing the window
    /// makes none again.
    #[test]
    fn force_layout_makes_the_rows_of_a_view_in_a_hidden_window() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
Item {
    id: root
    property bool shown: false
    property var names: ["a"]
    function fill() { view.forceLayout(); }
    PanelWindow {
        visible: root.shown
        ListView {
            id: view
            width: 100; height: 300
            model: ScriptModel { values: root.names }
            delegate: Item { required property var modelData; width: 100; height: 20 }
        }
    }
}"#,
            )
            .unwrap();
        rt.world.borrow_mut().frame_paced = true;
        rt.settle();
        let win = rt.world.borrow_mut().of_type("PanelWindow")[0];
        let lv = rt.world.borrow_mut().of_type("ListView")[0];
        let rows = |rt: &Runtime| rt.world.borrow().delegated[&lv].1.clone();
        let names = |n: &[&str]| Value::array(n.iter().map(|s| Value::str(s)).collect());
        rt.set(root, "names", names(&["a", "b", "c"]));
        rt.settle();
        assert_eq!(rows(&rt).len(), 1, "held while the window is hidden");
        rt.call_method(root, "fill", vec![]).unwrap().unwrap();
        rt.settle();
        let made = rows(&rt);
        assert_eq!(made.len(), 3, "forceLayout made them");
        rt.set(root, "shown", Value::Bool(true));
        rt.settle();
        rt.set_polish_wins(Some(win));
        rt.polish(&[win]);
        rt.settle();
        assert_eq!(rows(&rt), made, "showing the window made none again");
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    /// Quickshell deletes the QQuickWindow of a hidden layer window; the next one is laid out
    /// more than once as it gets its size, and QQuickItemViewPrivate::layout releases a row
    /// that is already leaving. A row removed while the window was hidden is gone when the
    /// window shows, without the view's `remove` transition; a row removed in a shown window
    /// runs it.
    #[test]
    fn rows_removed_in_a_hidden_panel_leave_without_transition_when_it_shows() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
Item {
    id: root
    property var names: ["a"]
    property string log: ""
    PanelWindow {
        visible: root.names.length > 0
        ListView {
            id: view
            width: 100; height: 300
            model: ScriptModel { values: root.names }
            add: Transition { NumberAnimation { property: "opacity"; from: 0; to: 1; duration: 200 } }
            remove: Transition { NumberAnimation { property: "x"; to: 120; duration: 200 } }
            delegate: Item {
                required property var modelData
                width: 100; height: 20
                onXChanged: if (x > 0 && x < 120) root.log += modelData + " moves;"
                onOpacityChanged: if (opacity > 0 && opacity < 1) root.log += modelData + " fades;"
                Component.onDestruction: root.log += modelData + " gone;"
            }
        }
    }
}"#,
            )
            .unwrap();
        rt.settle();
        let names = |n: &[&str]| Value::array(n.iter().map(|s| Value::str(s)).collect());
        let mut t = 0.0;
        let mut run = |rt: &mut Runtime, names: Value| {
            rt.set(root, "names", names);
            rt.settle();
            for _ in 0..20 {
                t += 16.0;
                rt.tick(t);
            }
            let log = rt.get(root, "log").to_js_string();
            rt.set(root, "log", Value::str(""));
            // Each thing a row did, once, in the order it first did it.
            log.split_inclusive(';').fold(String::new(), |mut l, s| {
                if !l.contains(s) {
                    l.push_str(s);
                }
                l
            })
        };
        // The window hides with the row's removal: the row stays as it is.
        assert_eq!(run(&mut rt, names(&[])), "");
        // It shows with another row: the old one is released at once, the new one fades in.
        assert_eq!(run(&mut rt, names(&["b"])), "a gone;b fades;");
        // In the shown window a removed row runs the transition.
        assert_eq!(run(&mut rt, names(&["c"])), "c fades;b moves;b gone;");
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    /// The first row of a layer window that has not shown yet appears as it is: the `add`
    /// transition runs for rows added once the window has drawn a frame, also while hidden.
    #[test]
    fn rows_added_before_a_panel_first_shows_run_no_add_transition() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
Item {
    id: root
    property var names: []
    property string log: ""
    PanelWindow {
        visible: root.names.length > 0
        ListView {
            width: 100; height: 300
            model: ScriptModel { values: root.names }
            add: Transition { NumberAnimation { property: "opacity"; from: 0; to: 1; duration: 200 } }
            delegate: Item {
                required property var modelData
                width: 100; height: 20
                onOpacityChanged: if (opacity > 0 && opacity < 1) root.log += modelData + " fades;"
                Component.onCompleted: root.log += modelData + " made;"
            }
        }
    }
}"#,
            )
            .unwrap();
        rt.world.borrow_mut().frame_paced = true;
        rt.settle();
        let win = rt.world.borrow_mut().of_type("PanelWindow")[0];
        let names = |n: &[&str]| Value::array(n.iter().map(|s| Value::str(s)).collect());
        let mut t = 0.0;
        let mut frames = 0;
        // The host: the window is paced while it shows, polished and then drawn each frame.
        let mut run = |rt: &mut Runtime, names: Value| {
            rt.set(root, "names", names);
            rt.settle();
            let shown = rt.get(win, "visible").truthy();
            rt.set_polish_wins(shown.then_some(win));
            for _ in 0..20 {
                t += 16.0;
                rt.tick(t);
                if shown {
                    rt.polish(&[win]);
                    frames += 1;
                    rt.world.borrow_mut().win_frames.insert(win, frames);
                }
            }
            let log = rt.get(root, "log").to_js_string();
            rt.set(root, "log", Value::str(""));
            log.split_inclusive(';').fold(String::new(), |mut l, s| {
                if !l.contains(s) {
                    l.push_str(s);
                }
                l
            })
        };
        assert_eq!(run(&mut rt, names(&["a"])), "a made;");
        assert_eq!(run(&mut rt, names(&["a", "b"])), "b made;b fades;");
        assert_eq!(run(&mut rt, names(&[])), "");
        assert_eq!(run(&mut rt, names(&["c"])), "c made;c fades;");
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn view_in_paced_window_applies_model_changes_at_polish() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
Item {
    id: root
    property var names: ["a"]
    PanelWindow {
        ListView {
            width: 100; height: 300
            model: ScriptModel { values: root.names }
            delegate: Item { required property var modelData; width: 100; height: 20 }
        }
    }
}"#,
            )
            .unwrap();
        rt.settle();
        let win = rt.world.borrow_mut().of_type("PanelWindow")[0];
        let lv = rt.world.borrow_mut().of_type("ListView")[0];
        rt.set_polish_wins([win]);
        let dels = |rt: &Runtime| rt.world.borrow().delegated[&lv].1.clone();
        let first = dels(&rt);
        assert_eq!(first.len(), 1);
        let names = |n: &[&str]| Value::array(n.iter().map(|s| Value::str(s)).collect());
        rt.set(root, "names", names(&["b", "a"]));
        rt.settle();
        rt.set(root, "names", names(&["c", "b", "a"]));
        rt.settle();
        assert_eq!(dels(&rt), first);
        assert_eq!(rt.get(lv, "count").to_number(), 3.0);
        assert_eq!(rt.held_windows(), vec![win]);
        rt.polish(&[win]);
        let after = dels(&rt);
        assert_eq!(after.len(), 3);
        assert_eq!(after[2], first[0]);
        assert!(rt.held_windows().is_empty());
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());

        // Dropped and re-added before the polish: a removal and an insertion, a fresh delegate.
        rt.set(root, "names", names(&["c", "b"]));
        rt.settle();
        rt.set(root, "names", names(&["c", "b", "a"]));
        rt.settle();
        rt.polish(&[win]);
        let again = dels(&rt);
        assert_eq!(&again[..2], &after[..2]);
        assert_ne!(again[2], after[2]);
        assert!(rt.world.borrow().held_gone.is_empty());
    }

