    #[test]
    fn view_destroyed_delegates_run_on_destruction() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
Item {
    id: root
    property int gone: 0
    property var names: ["a", "b", "c"]
    property var plain: ["x", "y"]
    property string last: ""
    ListView {
        id: lv
        width: 100; height: 300
        model: ScriptModel { values: root.names }
        delegate: Item {
            required property var modelData
            width: 100; height: 20
            Component.onDestruction: { root.gone++; root.last = modelData }
        }
    }
    ListView {
        id: animated
        width: 100; height: 300
        model: ScriptModel { values: root.names }
        remove: Transition { NumberAnimation { property: "opacity"; to: 0; duration: 500 } }
        delegate: Item {
            required property var modelData
            width: 100; height: 20
            Component.onDestruction: root.gone += 100
        }
    }
    Repeater {
        model: root.plain
        delegate: Item { Component.onDestruction: root.gone += 10000 }
    }
}"#,
            )
            .unwrap();
        rt.settle();
        rt.set(
            root,
            "names",
            Value::array(vec![Value::str("a"), Value::str("c")]),
        );
        rt.settle();
        assert_eq!(rt.get(root, "gone").to_number(), 1.0);
        assert_eq!(rt.get(root, "last").to_js_string().as_str(), "b");
        rt.tick(1000.0);
        rt.settle();
        assert_eq!(rt.get(root, "gone").to_number(), 101.0);
        rt.set(root, "plain", Value::array(vec![Value::str("z")]));
        rt.settle();
        assert_eq!(rt.get(root, "gone").to_number(), 20101.0);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

