    #[test]
    fn behavior_intercepts_writes_during_other_component_creation() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"Item {
                    id: root
                    property bool hov: false
                    property bool make: false
                    property bool reveal: hov
                    property real w: reveal ? 100 : 0
                    Behavior on w { NumberAnimation { duration: 100 } }
                    signal gone()
                    onGone: root.hov = false
                    Loader {
                        active: root.make
                        sourceComponent: Item {}
                    }
                }"#,
            )
            .unwrap();
        rt.set(root, "hov", Value::Bool(true));
        rt.settle();
        assert!(rt.tick(50.0));
        assert_eq!(rt.get(root, "w").to_number(), 50.0);
        // The Loader instantiates while the queued handler is still pending (a hover exit
        // delivered together with the enter that opens a popup).
        rt.world.borrow_mut().write(root, "make", Value::Bool(true));
        rt.emit(root, "gone", &[], vec![]);
        rt.settle();
        assert_eq!(rt.get(root, "w").to_number(), 50.0);
        rt.tick(100.0);
        rt.tick(300.0);
        assert_eq!(rt.get(root, "w").to_number(), 0.0);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

