    #[test]
    fn stackview_runs_push_and_pop_transitions_with_animators() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import QtQuick.Controls
Item {
    id: root
    property int acts: 0
    property int deacts: 0
    function go() { sv.push(b) }
    function back() { sv.pop() }
    StackView {
        id: sv
        width: 100; height: 100
        pushEnter: Transition {
            XAnimator { from: -40; to: 0; duration: 100 }
            NumberAnimation { property: "opacity"; from: 0; to: 1; duration: 100 }
        }
        pushExit: Transition {
            XAnimator { from: 0; to: 40; duration: 100 }
            NumberAnimation { property: "opacity"; from: 1; to: 0; duration: 100 }
        }
        popEnter: Transition { XAnimator { from: 40; to: 0; duration: 100 } }
        popExit: Transition { XAnimator { from: 0; to: -40; duration: 100 } }
        initialItem: Item { id: a; StackView.onDeactivated: root.deacts++ }
    }
    Item { id: b; StackView.onActivated: root.acts++ }
}"#,
            )
            .unwrap();
        rt.settle();
        let (sv, a, b) = (
            rt.id("sv").unwrap(),
            rt.id("a").unwrap(),
            rt.id("b").unwrap(),
        );
        rt.tick(0.0);
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.settle();
        rt.tick(50.0);
        rt.settle();
        assert!(rt.get(sv, "busy").truthy());
        assert!(
            rt.get(a, "visible").truthy(),
            "the exiting item stays visible while it animates"
        );
        assert!(
            (rt.get(b, "x").to_number() + 20.0).abs() < 1.0,
            "x {}",
            rt.get(b, "x").to_number()
        );
        assert!((rt.get(a, "x").to_number() - 20.0).abs() < 1.0);
        assert!((rt.get(b, "opacity").to_number() - 0.5).abs() < 0.05);
        assert_eq!(rt.get(root, "acts").to_number(), 0.0);
        rt.tick(120.0);
        rt.settle();
        assert!(!rt.get(sv, "busy").truthy());
        assert!(!rt.get(a, "visible").truthy());
        assert_eq!(rt.get(b, "x").to_number(), 0.0);
        assert_eq!(
            rt.get(a, "x").to_number(),
            0.0,
            "geometry restored once hidden"
        );
        assert_eq!(rt.get(a, "opacity").to_number(), 1.0);
        assert_eq!(rt.get(root, "acts").to_number(), 1.0);
        assert_eq!(rt.get(root, "deacts").to_number(), 1.0);
        rt.call_method(root, "back", vec![]).unwrap().unwrap();
        rt.settle();
        rt.tick(170.0);
        assert!((rt.get(a, "x").to_number() - 20.0).abs() < 1.0);
        assert!((rt.get(b, "x").to_number() + 20.0).abs() < 1.0);
        rt.tick(300.0);
        rt.settle();
        assert!(!rt.get(b, "visible").truthy());
        assert_eq!(rt.get(a, "x").to_number(), 0.0);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn long_change_handler_chain_runs_to_the_end() {
        // Each assignment runs its handler inside it, as Qt's NOTIFY emission does, however deep
        // the chain nests; only the JS stack bounds it. On a main-thread-sized stack, like
        // the shell's.
        std::thread::Builder::new()
            .stack_size(8 << 20)
            .spawn(long_change_handler_chain)
            .unwrap()
            .join()
            .unwrap();
    }

    fn long_change_handler_chain() {
        let n = 120;
        let mut src = String::from("Item { id: r; property int calls\nfunction go() { p0 = 1 }\n");
        for i in 0..n {
            src += &format!("property int p{i}\n");
            if i + 1 < n {
                src += &format!("onP{i}Changed: {{ calls++; p{} = p{i} }}\n", i + 1);
            } else {
                src += &format!("onP{i}Changed: calls++\n");
            }
        }
        src += "}";
        let mut rt = Runtime::new(None);
        let r = rt.load_str(&src).unwrap();
        rt.settle();
        let w = rt.world.clone();
        rt.call_method(r, "go", vec![]).unwrap().unwrap();
        // Before the main loop settles anything: the assignment ran the whole chain.
        assert_eq!(
            w.borrow_mut()
                .read(r, &format!("p{}", n - 1))
                .unwrap()
                .to_number(),
            1.0
        );
        assert_eq!(rt.get(r, "calls").to_number(), n as f64);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn members_after_block_on_one_line_register() {
        // Qt ends a function body or `{ }` block binding at its `}`: the handlers after it
        // on the same line are members, not part of the body.
        let mut rt = Runtime::new(None);
        let r = rt
            .load_str(
                "Item { property int a; property int b; property int c; property int d; property int e\n\
                 function go() { a = 1 } onAChanged: b++; onBChanged: c++\n\
                 onCChanged: { d++ } onDChanged: { e++ } }",
            )
            .unwrap();
        rt.settle();
        rt.call_method(r, "go", vec![]).unwrap().unwrap();
        rt.settle();
        let got: Vec<f64> = ["a", "b", "c", "d", "e"]
            .map(|p| rt.get(r, p).to_number())
            .to_vec();
        assert_eq!(got, [1.0; 5]);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn text_measured_on_read_is_not_the_readers_write() {
        let mut rt = Runtime::new(None);
        let causes = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let seen = causes.clone();
        rt.world.borrow_mut().text_measure = Some(Box::new(move |w, i| {
            let n = match w.read(i, "text") {
                Some(Value::Str(s)) => s.chars().count(),
                _ => 0,
            };
            w.write(i, "implicitWidth", Value::Num(n as f64 * 7.0));
            seen.borrow_mut().push(w.sched.cur());
        }));
        let root = rt
            .load_str(
                "Item { property real pad: 10; implicitWidth: t.implicitWidth + 2 * pad
                    Text { id: t; anchors.centerIn: parent; text: \"tip\" } }",
            )
            .unwrap();
        let t = rt.id("t").unwrap();
        rt.set(t, "text", Value::str("longer"));
        rt.set(root, "pad", Value::Num(12.0));
        rt.settle();
        assert_eq!(rt.get(root, "implicitWidth").to_number(), 6.0 * 7.0 + 24.0);
        let causes = causes.borrow();
        assert!(causes.len() >= 2, "{causes:?}");
        assert!(causes.iter().all(|c| *c == Cause::ROOT), "{causes:?}");
        assert!(
            !rt.errors().iter().any(|e| e.contains("binding loop")),
            "{:?}",
            rt.errors()
        );
    }

    /// Qt 6.12 prints `3 133.33 8.00 117.33` and no binding loop warning: `width` reads `x`
    /// while `x` is still pending, which enables `x` inside the read.
    #[test]
    fn pending_binding_enabled_by_its_reader_is_no_loop() {
        let dir = std::env::temp_dir().join(format!("flush-reader-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(
            dir.join("Bar.qml"),
            "import QtQuick\nimport QtQuick.Controls\nTabBar { id: root
                background: Item { Rectangle { id: ind
                    property real baseWidth: root.width / root.count
                    x: root.currentIndex * baseWidth + 8
                    width: ((root.currentIndex + 1) * baseWidth - 8) - x } }
                function ind() { return ind.baseWidth.toFixed(2) + ' ' + ind.x.toFixed(2) + ' ' + ind.width.toFixed(2) } }\n",
        )
        .unwrap();
        let f = dir.join("main.qml");
        std::fs::write(
            &f,
            "import QtQuick\nimport QtQuick.Controls\nItem { width: 400; height: 300
                property string got
                Bar { id: bar; width: 400; currentIndex: sv.currentIndex
                    Repeater { model: 3; delegate: TabButton { text: 't' } } }
                SwipeView { id: sv; currentIndex: bar.currentIndex; Item {} Item {} Item {} }
                Component.onCompleted: got = bar.count + ' ' + bar.ind() }\n",
        )
        .unwrap();
        let mut rt = Runtime::new(Some(dir.clone()));
        let root = rt.load_file(&f).unwrap();
        rt.settle();
        assert_eq!(rt.get(root, "got").to_js_string(), "3 133.33 8.00 117.33");
        assert!(
            !rt.errors().iter().any(|e| e.contains("binding loop")),
            "{:?}",
            rt.errors()
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_copy_of_a_delegate_has_the_size_of_its_text() {
        // The second delegate takes the values of the first one's bindings as they were when
        // its bindings were enabled (`plan::Post`): the Text was not laid out yet then.
        let mut rt = Runtime::new(None);
        rt.world.borrow_mut().text_measure = Some(Box::new(|w, i| {
            let n = match w.read(i, "text") {
                Some(Value::Str(s)) => s.chars().count(),
                _ => 0,
            };
            w.write(i, "implicitWidth", Value::Num(n as f64 * 7.0));
        }));
        let root = rt
            .load_str(
                "Item { id: root; property var made: []
                    Repeater { model: 3; Item {
                        implicitWidth: t.implicitWidth + 24
                        Text { id: t; text: \"abcdef\" }
                        Component.onCompleted: root.made.push(this) } } }",
            )
            .unwrap();
        rt.settle();
        let Value::Obj(made) = rt.get(root, "made") else {
            panic!()
        };
        let made: Vec<usize> = (made.borrow().array.iter().flatten())
            .map(|v| match v {
                Value::Item(i) => *i,
                v => panic!("{v:?}"),
            })
            .collect();
        let widths: Vec<f64> = (made.iter())
            .map(|&i| rt.get(i, "implicitWidth").to_number())
            .collect();
        assert_eq!(widths, [6.0 * 7.0 + 24.0; 3]);
    }

    #[test]
    fn binding_loop_report_names_the_site_and_logs_once() {
        let dir = std::env::temp_dir().join(format!("loop-site-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let f = dir.join("Looping.qml");
        std::fs::write(
            &f,
            "import QtQuick\nItem { property int k; property int a: b + k + 1; property int b: a + 1 }\n",
        )
        .unwrap();
        let mut rt = Runtime::new(Some(dir.clone()));
        let root = rt.load_file(&f).unwrap();
        rt.settle();
        let errs = rt.errors();
        let e = errs
            .iter()
            .find(|e| e.starts_with("binding loop detected"))
            .unwrap_or_else(|| panic!("{errs:?}"));
        assert!(e.ends_with(&format!("(Item in {})", f.display())), "{e}");
        let reported = rt.world.borrow().loop_reported.len();
        assert_eq!(reported, 1, "{errs:?}");
        // The same loop again (a shell takes the errors every frame) is not logged again.
        let _ = rt.take_errors();
        rt.set(root, "k", Value::Num(1.0));
        rt.settle();
        assert_eq!(rt.world.borrow().loop_reported.len(), 1);
        let _ = root;
    }

