    #[test]
    fn signal_connect_and_disconnect_call_functions_in_connection_order() {
        // Qt 6.12 (PySide6) log of the same component; `this` of a function connected without
        // a receiver (the global object in Qt) is not logged.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    signal sig(int a)
    signal other(int a)
    property int w: 0
    property string out: ""
    onSig: (a) => out += "h" + a + ";"
    onOther: (a) => out += "o" + a + ";"
    Item { id: recv; objectName: "recv"; function m(a) { root.out += "m" + a + "this=" + this.objectName + ";" } }
    Item { id: gone; function m(a) { root.out += "gone" + a + ";" } }
    function f1(a) { out += "f1:" + a + ";" }
    function f2(a) { out += "f2:" + a + ";" }
    function t(f) { try { f(); } catch (e) { out += "E[" + e.name + ":" + e.message + "];" } }
    function go() {
        out += "typeof:" + typeof root.sig + "," + typeof root.wChanged + "," + typeof sig + ";";
        sig.connect(f1); root.sig.connect(f2); root.sig.connect(recv, recv.m); root.sig.connect(other);
        root.sig.connect(f1); root.sig.connect(gone, gone.m); gone.destroy();
    }
    function go2() {
        sig(1);
        out += "|";
        root.sig.disconnect(f1); sig(2);
        out += "|";
        t(() => root.sig.disconnect(f1));
        root.sig.disconnect(recv, recv.m); root.sig.disconnect(other); root.sig.disconnect(f2); sig(4);
        out += "|";
        root.wChanged.connect(() => out += "wc" + w + ";"); w = 5;
        out += "|";
        t(() => root.sig.connect(5)); t(() => root.sig.connect()); t(() => root.sig.disconnect(recv, 5));
        t(() => forceActiveFocus.connect(f1));
        out += "|";
        root.sig.connect(function(a) { out += "anon" + a + ";"; throw new Error("boom") });
        root.sig.connect(f1);
        sig(6);
    }
}"#,
            )
            .unwrap();
        rt.settle();
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.settle();
        rt.call_method(root, "go2", vec![]).unwrap().unwrap();
        rt.settle();
        assert_eq!(
            rt.get(root, "out").to_js_string(),
            "typeof:function,function,function;h1;f1:1;f2:1;m1this=recv;o1;f1:1;|h2;f2:2;m2this=recv;o2;\
             |h4;|wc5;|E[Error:Function.prototype.connect: target is not a function];\
             E[Error:Function.prototype.connect: no arguments given];\
             E[Error:Function.prototype.disconnect: target is not a function];\
             E[Error:Function.prototype.connect: this object is not a signal];|h6;anon6;f1:6;"
        );
        let errs = rt.errors();
        assert!(
            errs.len() == 1 && errs[0].ends_with("onSig (connected function): boom"),
            "{errs:?}"
        );
    }

    #[test]
    fn js_connection_index_forgets_disconnected_and_destroyed_ends() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property int hits: 0
    function hit() { hits++ }
    Component { id: comp; Item { signal ping() } }
    Item { id: sender; signal ping() }
    function churn() {
        for (var i = 0; i < 200; i++) {
            var o = comp.createObject(root);
            o.ping.connect(root, root.hit);
            o.ping();
            o.destroy();
        }
    }
    function dropRoot() {
        var r = comp.createObject(root);
        r.ping.connect(r, root.hit);
        sender.ping.connect(r, root.hit);
        r.ping.connect(root, root.hit);
        r.destroy();
    }
    function link() { sender.ping.connect(root, root.hit); sender.ping() }
    function unlink() { sender.ping.disconnect(root, root.hit); sender.ping() }
}"#,
            )
            .unwrap();
        rt.settle();
        // Every listed key still has a connection whose sender or receiver is that object.
        let exact = |rt: &Runtime| {
            let w = rt.world.borrow();
            for (o, keys) in &w.js_conns_of {
                for k in keys {
                    let c = w.js_conns.get(k).map_or(&[][..], Vec::as_slice);
                    assert!(
                        k.0 == *o && !c.is_empty() || c.iter().any(|c| c.receiver() == Some(*o)),
                        "{o} lists {k:?} without a connection"
                    );
                }
            }
            for (k, c) in &w.js_conns {
                for o in std::iter::once(k.0).chain(c.iter().filter_map(JsConn::receiver)) {
                    assert!(w.js_conns_of[&o].contains(k), "{o} misses {k:?}");
                }
            }
            w.js_conns_of.len()
        };
        rt.call_method(root, "churn", vec![]).unwrap().unwrap();
        rt.settle();
        assert_eq!(rt.get(root, "hits").to_number(), 200.0);
        assert_eq!(exact(&rt), 0);
        rt.call_method(root, "dropRoot", vec![]).unwrap().unwrap();
        rt.settle();
        assert_eq!(exact(&rt), 0);
        rt.call_method(root, "link", vec![]).unwrap().unwrap();
        assert_eq!(exact(&rt), 2);
        rt.call_method(root, "unlink", vec![]).unwrap().unwrap();
        assert_eq!(rt.get(root, "hits").to_number(), 201.0);
        assert_eq!(exact(&rt), 0);
        assert!(rt.world.borrow().js_conns.is_empty());
    }

    #[test]
    fn unqualified_signals_resolve_on_the_scope_object_then_the_context_roots() {
        // Qt 6.12 (PySide6, offscreen) logs of the same component, in this order: "ROOT cw",
        // "OWN 7o ReferenceError:nosuchChanged is not defined true", "TIMER tT function function",
        // "CHILD x function function function".
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property int x2
    property string log: ""
    property string out: ""
    function cb() { log += "c" }
    Component.onCompleted: {
        x2Changed.connect(cb); widthChanged.connect(function(){ log += "w" })
        x2 = 3; width = 4
        out += "ROOT " + log + ";"
    }
    Item {
        property string l: ""
        Component.onCompleted: {
            x2Changed.connect(function(){ l += "x" })
            root.x2 = 5
            root.out += "CHILD " + l + " " + typeof x2Changed + " " + typeof widthChanged + " " + typeof cb + ";"
        }
    }
    Timer {
        property string l: ""
        onTriggered: l += "t"
        Component.onCompleted: {
            triggered.connect(function(){ l += "T" }); triggered()
            root.out += "TIMER " + l + " " + typeof triggered + " " + typeof runningChanged + ";"
        }
    }
    Item {
        property int own
        signal mine(int a)
        Component.onCompleted: {
            var s = ""; mine.connect(function(a){ s += a }); mine(7)
            ownChanged.connect(function(){ s += "o" }); own = 1
            try { nosuchChanged } catch (e) { s += " " + e.name + ":" + e.message }
            root.out += "OWN " + s + " " + (typeof x2Changed === "function") + ";"
        }
    }
}"#,
            )
            .unwrap();
        rt.settle();
        assert_eq!(
            rt.get(root, "out").to_js_string(),
            "ROOT cw;OWN 7o ReferenceError:nosuchChanged is not defined true;\
             TIMER tT function function;CHILD x function function function;"
        );
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn signal_connections_follow_qt_lifetime_and_emission_snapshot() {
        // Qt 6.12 (PySide6): destroying the receiver (`this`, or the object of a connected signal)
        // disconnects; destroying the object a connected function was declared in does not.
        // Connections made during an emission wait for the next one; ones dropped during it
        // are skipped. `disconnect` matches the (receiver, function) pair.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    signal sig(int a)
    property string out: ""
    property var k
    function record(s) { out += s + ";" }
    Component {
        id: comp
        Item {
            property string tag
            signal relay(int a)
            onRelay: (a) => root.record("relay" + a)
            function m(a) { root.record(tag + a) }
            function arrow(sink) { return (a) => sink("arrow" + a) }
            function withThis(sink) { return function(a) { sink("this=" + this.objectName + a) } }
        }
    }
    function f1(a) { record("f1:" + a); sig.disconnect(f1); sig.disconnect(f2); sig.connect(f3) }
    function f2(a) { record("f2:" + a) }
    function f3(a) { record("f3:" + a) }
    function go() {
        k = comp.createObject(root, { objectName: "k" });
        const a = comp.createObject(root, { tag: "a" });
        const b = comp.createObject(root);
        const s = comp.createObject(root);
        const g = comp.createObject(root);
        const d = comp.createObject(root);
        sig.connect(a, a.m);
        sig.connect(b, (x) => record("b" + x));
        sig.connect(s.relay);
        sig.connect(k, g.withThis(record));
        root.sig.connect(d.arrow(record));
        sig.connect(f1);
        sig.connect(f2);
        sig(0);
        for (const o of [a, b, s, g, d]) o.destroy();
    }
    function go2() {
        out += "|";
        sig(1);
        out += "|";
        sig.connect(k, f2); sig.disconnect(f2); sig(2);
        out += "|";
        sig.disconnect(k, f2); sig(3);
        k.destroy();
    }
    function go3() {
        out += "|";
        sig(4);
    }
}"#,
            )
            .unwrap();
        rt.settle();
        for f in ["go", "go2", "go3"] {
            rt.call_method(root, f, vec![]).unwrap().unwrap();
            rt.settle();
        }
        assert_eq!(
            rt.get(root, "out").to_js_string(),
            "a0;b0;relay0;this=k0;arrow0;f1:0;|this=k1;arrow1;f3:1;|this=k2;arrow2;f3:2;f2:2;\
             |this=k3;arrow3;f3:3;|arrow4;f3:4;"
        );
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn calling_a_signal_with_too_few_arguments_throws() {
        // Qt 6.12 (PySide6): QObjectMethod::callInternal throws `Error: Insufficient arguments`
        // and emits nothing; extra arguments are ignored.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    signal two(int a, string b)
    signal none()
    property string out: ""
    onTwo: (a, b) => out += "two(" + a + "," + b + ");"
    onNone: out += "none;"
    function t(f) { try { f(); out += "ok;" } catch (e) { out += "E[" + e.name + ":" + e.message + "|" + (e instanceof TypeError) + "];" } }
    function go() {
        t(() => root.two(1));
        t(() => root.two());
        t(() => root.two(1, "x", 3));
        t(() => two(5));
        t(() => root.none(1, 2));
        t(() => { var f = root.two; f(7) });
    }
}"#,
            )
            .unwrap();
        rt.settle();
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(
            rt.get(root, "out").to_js_string(),
            "E[Error:Insufficient arguments|false];E[Error:Insufficient arguments|false];\
             two(1,x);ok;E[Error:Insufficient arguments|false];none;ok;\
             E[Error:Insufficient arguments|false];"
        );
    }

    #[test]
    fn calling_a_cpp_signal_with_too_few_arguments_throws() {
        // Qt 6.12 (PySide6): C++ signals are checked against their qmltypes `Parameter`s like
        // QML ones; extra arguments are dropped, a handler sees the declared parameter names,
        // and an overloaded signal (`toggled(QObject*)` + its default-argument clone
        // `toggled()`) only throws when no overload fits.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import QtQuick.Controls
Item {
    id: root
    property string out: ""
    Timer { id: tm; onTriggered: root.out += "trig;" }
    MouseArea { id: ma; onClicked: root.out += "clicked(" + mouse + ");" }
    Action { id: ac }
    ListModel { id: lm }
    Connections { target: tm; function onTriggered() { root.out += "n" + arguments.length + ";" } }
    function t(n, f) { try { f(); out += n + ":ok;" } catch (e) { out += n + ":E[" + e.name + ":" + e.message + "];" } }
    function go() {
        t("trig0", () => tm.triggered());
        t("trig2", () => tm.triggered(1, 2));
        t("click0", () => ma.clicked());
        t("click1", () => ma.clicked(null));
        t("ref", () => { var f = ma.clicked; f() });
        t("tog0", () => ac.toggled());
        t("dc1", () => lm.dataChanged(1));
    }
}"#,
            )
            .unwrap();
        rt.settle();
        rt.call_method(root, "go", vec![]).unwrap().unwrap();
        rt.settle();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(
            rt.get(root, "out").to_js_string(),
            "trig;n0;trig0:ok;trig;n0;trig2:ok;click0:E[Error:Insufficient arguments];\
             clicked(null);click1:ok;ref:E[Error:Insufficient arguments];tog0:ok;\
             dc1:E[Error:Unable to determine callable overload.  Candidates are:\n    \
             dataChanged(QModelIndex,QModelIndex)\n    \
             dataChanged(QModelIndex,QModelIndex,QList<int>)];"
        );
    }

