    #[test]
    fn call_later_runs_each_function_once_with_its_last_arguments() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem { property int n: 0; property string a: \"\"; property string err: \"\"\n function bump(x) { n += 1; a += x }\n Component.onCompleted: { Qt.callLater(bump, \"1\"); Qt.callLater(bump, \"2\"); Qt.callLater(bump, \"3\"); Qt.callLater(function () { Qt.callLater(bump, \"4\") })\n try { Qt.callLater() } catch (e) { err += e.message + \";\" }\n try { Qt.callLater(5) } catch (e) { err += e.message } } }\n",
            )
            .unwrap();
        rt.settle();
        assert!(rt.later_pending());
        rt.run_later();
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(rt.get(root, "a").to_js_string(), "3");
        assert!(
            rt.later_pending(),
            "a call queued while the queue runs waits a turn"
        );
        rt.run_later();
        assert_eq!(rt.get(root, "a").to_js_string(), "34");
        assert_eq!(rt.get(root, "n").to_number(), 2.0);
        assert!(!rt.later_pending());
        assert_eq!(
            rt.get(root, "err").to_js_string(),
            "Qt.callLater: no arguments given;Qt.callLater: first argument not a function or signal"
        );
    }

    /// A repeated call moves to the end of the queue (PySide6 6.12: `callLater(a, 1);
    /// callLater(b, 1); callLater(a, 2)` runs b(1) then a(2)).
    #[test]
    fn call_later_requeues_a_repeated_function_at_the_end() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem { property string log: \"\"\n function a(x) { log += \"a\" + x }\n function b(x) { log += \"b\" + x }\n Component.onCompleted: { Qt.callLater(a, 1); Qt.callLater(b, 1); Qt.callLater(a, 2) } }\n",
            )
            .unwrap();
        rt.settle();
        rt.tick(16.0);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(rt.get(root, "log").to_js_string(), "b1a2");
    }

    /// Under a host with a loop of its own (`World::posted_yield`) a tick delivers one turn
    /// of the posted events before the clock's sources and one after, as Qt's loop goes back
    /// to its timers and frames after QCoreApplication::sendPostedEvents: a function that
    /// calls `Qt.callLater` with itself without end leaves the Timer next to it its time.
    /// (Quickshell 0.3.2 on Qt 6.12 draws 60 frames a second next to such a chain.)
    #[test]
    fn a_chain_of_posted_events_returns_to_the_host_after_a_turn() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem { property int n: 0; property int t: 0\n function again() { n += 1; Qt.callLater(again) }\n Timer { interval: 5; running: true; onTriggered: t = n }\n Component.onCompleted: Qt.callLater(again) }\n",
            )
            .unwrap();
        rt.settle();
        rt.world.borrow_mut().posted_yield = true;
        assert!(rt.tick(0.0), "the chain asks for the next turn");
        assert_eq!(rt.get(root, "n").to_number(), 2.0);
        assert!(rt.tick(5.0));
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(rt.get(root, "n").to_number(), 4.0);
        assert_eq!(
            rt.get(root, "t").to_number(),
            4.0,
            "the Timer fired in its tick"
        );
        rt.world.borrow_mut().posted_yield = false;
        rt.tick(6.0);
        assert_eq!(
            rt.get(root, "n").to_number(),
            2004.0,
            "the turns of a tick end"
        );
    }

    #[test]
    fn call_later_skips_calls_whose_object_was_destroyed() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                "import QtQuick\nItem { id: r; property int n: 0\n Component { id: c; Item { function bump() { r.n += 1 }\n Component.onCompleted: { Qt.callLater(bump); Qt.callLater(() => r.n += 10) } } }\n Component.onCompleted: { c.createObject(r); c.createObject(r).destroy() } }\n",
            )
            .unwrap();
        rt.settle();
        rt.tick(16.0);
        rt.tick(16.0);
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
        assert_eq!(rt.get(root, "n").to_number(), 11.0);
    }
