    #[test]
    fn binding_dependents_update_depth_first_like_qt() {
        // BluetoothStatus: a device leaving `connected` reaches `all` through `conn` before
        // `paired` updates, so the ScriptModel drops its delegate and makes a fresh one
        // (an expanded BluetoothDeviceItem collapses on disconnect).
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
ListView {
    id: root
    width: 100; height: 300
    property QtObject a: QtObject { property string name: "a"; property bool connected: true }
    property QtObject b: QtObject { property string name: "b"; property bool connected: false }
    property var devs: [a, b]
    property list<var> conn: devs.filter(d => d.connected)
    property list<var> paired: devs.filter(d => !d.connected)
    property list<var> all: [...conn, ...paired]
    model: ScriptModel { values: root.all }
    delegate: Item { required property var modelData; property bool expanded; width: 100; height: 20 }
}"#,
            )
            .unwrap();
        rt.settle();
        let dels = |rt: &Runtime| rt.world.borrow().delegated[&root].1.clone();
        let before = dels(&rt);
        assert_eq!(before.len(), 2);
        rt.set(before[0], "expanded", Value::Bool(true));
        let a = rt.get(root, "a");
        let Value::Item(a) = a else { panic!("{a:?}") };
        rt.set(a, "connected", Value::Bool(false));
        rt.settle();
        let after = dels(&rt);
        assert_eq!(after.len(), 2);
        assert_ne!(after[0], before[0]);
        assert_eq!(after[1], before[1]);
        assert!(rt.world.borrow().dead.contains(&before[0]));
        assert!(!rt.get(after[0], "expanded").truthy());
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn binding_reconnects_skipped_guards_last_like_qt() {
        // BluetoothStatus on Pair: pairing `a` made `paired` read `a.connected` before
        // `b.paired`, so Qt dropped and reconnected its `b.paired` guard after `unpaired`'s.
        // Pairing `b` then updates `unpaired` first: `all` briefly lacks `b`, the ScriptModel
        // drops its row and an expanded BluetoothDeviceItem collapses.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
ListView {
    id: root
    width: 100; height: 300
    property QtObject a: QtObject { property string name: "a"; property bool paired; property bool connected }
    property QtObject b: QtObject { property string name: "b"; property bool paired; property bool connected }
    property var devs: [a, b]
    property string log
    property list<var> paired: devs.filter(d => d.paired && !d.connected)
    property list<var> unpaired: devs.filter(d => !d.paired && !d.connected)
    property list<var> all: [...paired, ...unpaired]
    onPairedChanged: log += "paired,"
    onUnpairedChanged: log += "unpaired,"
    model: ScriptModel { values: root.all }
    delegate: Item { required property var modelData; property bool expanded; width: 100; height: 20 }
}"#,
            )
            .unwrap();
        rt.settle();
        let item = |rt: &Runtime, n: &str| match rt.get(root, n) {
            Value::Item(i) => i,
            v => panic!("{v:?}"),
        };
        let (a, b) = (item(&rt, "a"), item(&rt, "b"));
        rt.set(a, "paired", Value::Bool(true));
        rt.settle();
        let dels = |rt: &Runtime| rt.world.borrow().delegated[&root].1.clone();
        let before = dels(&rt);
        assert_eq!(before.len(), 2);
        rt.set(before[1], "expanded", Value::Bool(true));
        rt.set(root, "log", Value::str(""));
        rt.set(b, "paired", Value::Bool(true));
        rt.settle();
        assert_eq!(rt.get(root, "log").to_js_string(), "unpaired,paired,");
        let after = dels(&rt);
        assert_eq!(after.len(), 2);
        assert_eq!(after[0], before[0]);
        assert_ne!(after[1], before[1]);
        assert!(rt.world.borrow().dead.contains(&before[1]));
        assert!(!rt.get(after[1], "expanded").truthy());
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    #[test]
    fn bindable_property_notifies_last_installed_observer_first_like_qt() {
        // BluetoothStatus on Pair: BluetoothDevice.paired is a Quickshell bindable property, so
        // `unpaired` (last to install its trigger) updates before `paired`; `all` briefly lacks
        // the device, the ScriptModel drops its row and an expanded BluetoothDeviceItem collapses.
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
import Rustshell
ListView {
    id: root
    width: 100; height: 300
    property var devs: []
    property string log
    property list<var> paired: devs.filter(d => d.paired)
    property list<var> unpaired: devs.filter(d => !d.paired)
    property list<var> all: [...paired, ...unpaired]
    onPairedChanged: log += "paired,"
    onUnpairedChanged: log += "unpaired,"
    model: ScriptModel { values: root.all }
    delegate: Item { required property var modelData; property bool expanded; width: 100; height: 20 }
}"#,
            )
            .unwrap();
        let (a, b) = {
            let mut w = rt.world.borrow_mut();
            let a = crate::types::native_singleton(&mut w, "BluetoothDevice");
            let b = crate::types::native_singleton(&mut w, "BluetoothDevice");
            (a, b)
        };
        rt.set(a, "paired", Value::Bool(true));
        rt.set(b, "paired", Value::Bool(false));
        rt.set(
            root,
            "devs",
            Value::array(vec![Value::Item(a), Value::Item(b)]),
        );
        rt.settle();
        let dels = |rt: &Runtime| rt.world.borrow().delegated[&root].1.clone();
        let before = dels(&rt);
        assert_eq!(before.len(), 2);
        rt.set(before[1], "expanded", Value::Bool(true));
        rt.set(root, "log", Value::str(""));
        rt.set(b, "paired", Value::Bool(true));
        rt.settle();
        assert_eq!(rt.get(root, "log").to_js_string(), "unpaired,paired,");
        let after = dels(&rt);
        assert_eq!(after.len(), 2);
        assert_eq!(after[0], before[0]);
        assert_ne!(after[1], before[1]);
        assert!(!rt.get(after[1], "expanded").truthy());
        assert!(rt.errors().is_empty(), "{:?}", rt.errors());
    }

    /// Siblings are finalized last created first, so the last one connects to `ready` first
    /// and is notified first.
