#[cfg(test)]
mod property_value_items {
    use super::*;
    #[test]
    fn explicit_parent_makes_property_value_a_visual_child() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property Item bg: Rectangle { parent: root }
    property Item loose: Rectangle {}
}"#,
            )
            .unwrap();
        rt.settle();
        let w = rt.world.borrow();
        let pv = |name: &str| {
            let Some(Prop {
                value: Value::Item(c),
                ..
            }) = w.items[root].props.get(name)
            else {
                panic!("{name}")
            };
            let c = *c;
            w.items[c].props.contains_key("\x01propval")
        };
        assert!(!pv("bg"));
        assert!(pv("loose"));
    }

    // Qt sets an explicit `parent:` of a property-value item with the other bindings, after
    // the object's children exist: WMouseAreaButton's `background: Rectangle { parent: root }`
    // paints over the content declared in a TaskViewWorkspace. Order as Quickshell 0.3.2
    // printed it for these files: base0,base1,v0,a,b,extra,bg,moved.
    #[test]
    fn explicit_parent_property_value_stacks_above_children() {
        let tmp = tempfile::tempdir().unwrap();
        let d = tmp.path();
        std::fs::write(
            d.join("W.qml"),
            "import QtQuick\nMouseArea {\n id: root\n Item { objectName: \"base0\" }\n property Item background: Rectangle { parent: root; objectName: \"bg\" }\n Item { objectName: \"base1\" }\n}\n",
        )
        .unwrap();
        std::fs::write(
            d.join("V.qml"),
            "import QtQuick\nW {\n id: v\n Item { objectName: \"v0\" }\n property Item extra: Rectangle { parent: v; objectName: \"extra\" }\n}\n",
        )
        .unwrap();
        std::fs::write(
            d.join("main.qml"),
            "import QtQuick\nItem {\n property Item one: V {\n id: one\n Item { objectName: \"a\" }\n Item { objectName: \"b\" }\n }\n property Item two: Item {\n Item { objectName: \"moved\"; parent: one }\n }\n}\n",
        )
        .unwrap();
        let mut rt = Runtime::new(Some(d.to_path_buf()));
        let root = rt.load_file(&d.join("main.qml")).unwrap();
        rt.settle();
        let mut w = rt.world.borrow_mut();
        let Some(Value::Item(one)) = w.read(root, "one") else {
            panic!("one")
        };
        let kids = w.items[one].children.clone();
        let names: Vec<String> = kids
            .into_iter()
            .map(|c| {
                w.read(c, "objectName")
                    .map(|v| v.to_js_string())
                    .unwrap_or_default()
            })
            .collect();
        assert_eq!(names.join(","), "base0,base1,v0,a,b,extra,bg,moved");
    }
}
#[cfg(test)]
mod explicit_animation_bindings {
    use super::*;
    // WBarAttachedPanelContent: `sourceEdgeMargin: -(implicitHeight + ...)`, opened by
    // `openAnim.start()`; a later implicitHeight change must not snap the panel shut again.
    #[test]
    fn started_animation_removes_the_binding_it_animates() {
        let mut rt = Runtime::new(None);
        let root = rt
            .load_str(
                r#"import QtQuick
Item {
    id: root
    property real h: 10
    property alias m: pc.m
    property alias b: pc.b
    Item {
        id: pc
        property real m: -(implicitHeight + 12)
        property real b: root.h
        implicitHeight: root.h
        Behavior on b { NumberAnimation { duration: 100 } }
        Component.onCompleted: anim.start()
        PropertyAnimation { id: anim; target: pc; properties: "m"; to: 12; duration: 200 }
    }
}"#,
            )
            .unwrap();
        rt.settle();
        rt.tick(0.0);
        rt.tick(300.0);
        assert_eq!(rt.get(root, "m").to_number(), 12.0);
        rt.set(root, "h", Value::Num(50.0));
        rt.settle();
        rt.tick(500.0);
        assert_eq!(rt.get(root, "m").to_number(), 12.0);
        assert_eq!(
            rt.get(root, "b").to_number(),
            50.0,
            "a Behavior keeps the binding"
        );
    }
}
