        let root = rt
            .load_str(
                r#"Item {
    id: root
    property var mon: monitorComp.createObject(root)
    Component { id: monitorComp; QtObject {
        property real brightness
        property real mb: brightness
        property var seen: []
        Behavior on mb { NumberAnimation { duration: 200 } }
        onMbChanged: seen.push(mb)
    } }
}"#,
            )
            .unwrap();
        rt.settle();
        let Value::Item(mon) = rt.get(root, "mon") else {
            panic!()
        };
        rt.tick(0.0);
        rt.set(mon, "brightness", Value::Num(0.5));
        let mut t = 0.0;
